css:
@property --mfm-flow-p { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --mfm-flow-fade { syntax: '<length>'; inherits: false; initial-value: 0px; }

.mfm-flow {
  /* re-theme with these four */
  --mfm-flow-bg: oklch(0.205 0.017 55);
  --mfm-flow-ink: oklch(0.95 0.018 82);
  --mfm-flow-accent: oklch(0.81 0.135 66);
  --mfm-flow-bad: oklch(0.72 0.17 30);

  --mfm-flow-mute: color-mix(in oklch, var(--mfm-flow-ink) 56%, var(--mfm-flow-bg));
  --mfm-flow-line: color-mix(in oklch, var(--mfm-flow-ink) 12%, transparent);
  --mfm-flow-raise: color-mix(in oklch, var(--mfm-flow-ink) 4.5%, transparent);
  --mfm-flow-tint: color-mix(in oklch, var(--mfm-flow-accent) 14%, transparent);
  --mfm-flow-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-flow-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px; height: 458px;
  display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top" "bar" "stage" "foot";
  padding: 16px 18px 14px; margin: 0;
  border-radius: 18px; border: 1px solid var(--mfm-flow-line);
  color: var(--mfm-flow-ink);
  background:
    radial-gradient(120% 70% at 100% 0%, color-mix(in oklch, var(--mfm-flow-accent) 13%, transparent), transparent 62%),
    var(--mfm-flow-bg);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --mfm-flow-p .9s var(--mfm-flow-spring);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-flow-accent); outline-offset: 2px; }

  & .mfm-flow-top { grid-area: top; display: flex; align-items: center; justify-content: space-between; gap: 12px; }
  & .mfm-flow-brand {
    display: inline-flex; align-items: center; gap: 7px;
    font-size: 12.5px; font-weight: 600; letter-spacing: .01em;
    & svg { width: 17px; height: 17px; color: var(--mfm-flow-accent); }
  }
  & .mfm-flow-count {
    font: 500 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mfm-flow-mute);
    font-variant-numeric: tabular-nums; letter-spacing: .04em;
    & b { color: var(--mfm-flow-ink); font-weight: 600; display: inline-block; animation: mfm-flow-tick .45s var(--mfm-flow-out); }
  }

  & .mfm-flow-track {
    grid-area: bar; position: relative; height: 3px; margin: 13px 0 4px;
    border-radius: 3px; background: var(--mfm-flow-line);
    & i {
      position: absolute; inset: 0; border-radius: inherit; transform-origin: left;
      transform: scaleX(calc(0.025 + var(--mfm-flow-p) * 0.975));
      background: linear-gradient(90deg, color-mix(in oklch, var(--mfm-flow-accent) 55%, var(--mfm-flow-bg)), var(--mfm-flow-accent));
    }
    &::after {
      content: ""; position: absolute; top: 50%; width: 9px; height: 9px; border-radius: 50%;
      left: calc((0.025 + var(--mfm-flow-p) * 0.975) * 100%); translate: -50% -50%;
      background: var(--mfm-flow-accent);
      box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-flow-accent) 22%, transparent), 0 0 18px var(--mfm-flow-accent);
    }
  }

  & .mfm-flow-stage {
    grid-area: stage; min-height: 0; overflow: auto; padding: 16px 2px 8px; scrollbar-width: none;
    /* fade the bottom edge only while there is more to scroll (scroll-driven, see @supports below) */
    mask-image: linear-gradient(#000 calc(100% - var(--mfm-flow-fade)), transparent);
  }

  & .mfm-flow-q { display: grid; align-content: start; }
  & .mfm-flow-qnum {
    display: flex; align-items: center; gap: 6px; margin: 0 0 8px;
    font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; color: var(--mfm-flow-accent);
    & svg { width: 12px; height: 12px; }
  }
  & .mfm-flow-title {
    display: block; margin: 0; outline: none;
    font-size: clamp(1.06rem, 0.72rem + 3.5cqi, 1.36rem); line-height: 1.22;
    font-weight: 640; letter-spacing: -0.018em; text-wrap: balance;
  }
  & .mfm-flow-sub { margin: 6px 0 0; color: var(--mfm-flow-mute); font-size: 13px; text-wrap: pretty; }

  & .mfm-flow-opts { display: grid; gap: 7px; margin-top: 14px; }
  & .mfm-flow-opt {
    position: relative; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px;
    min-height: 41px; padding: 6px 12px 6px 8px; border-radius: 11px; cursor: pointer;
    background: var(--mfm-flow-raise); border: 1px solid var(--mfm-flow-line);
    font-weight: 500; user-select: none;
    transition: background-color .2s, border-color .2s, transform .4s var(--mfm-flow-spring);
    animation: mfm-flow-rise .55s var(--mfm-flow-out) both;
    animation-delay: calc(var(--i) * 48ms + 90ms);
    & input { position: absolute; inset: 0; margin: 0; opacity: 0; pointer-events: none; }
    & kbd {
      width: 24px; height: 24px; display: grid; place-items: center; border-radius: 7px;
      font: 650 11px/1 ui-monospace, Menlo, monospace; color: var(--mfm-flow-mute);
      border: 1px solid var(--mfm-flow-line); background: color-mix(in oklch, var(--mfm-flow-bg) 60%, transparent);
      transition: background-color .2s, color .2s, border-color .2s;
    }
    & .mfm-flow-check { width: 16px; height: 16px; color: var(--mfm-flow-accent); opacity: 0; scale: .4; transition: opacity .2s, scale .45s var(--mfm-flow-spring); }
    &:hover { background: color-mix(in oklch, var(--mfm-flow-accent) 8%, transparent); border-color: color-mix(in oklch, var(--mfm-flow-accent) 34%, transparent); }
    &:active { transform: scale(.985); }
    &:has(input:focus-visible) { outline: 2px solid var(--mfm-flow-accent); outline-offset: 2px; }
    &:has(input:checked) {
      background: var(--mfm-flow-tint); border-color: var(--mfm-flow-accent);
      & kbd { background: var(--mfm-flow-accent); color: var(--mfm-flow-bg); border-color: transparent; }
      & .mfm-flow-check { opacity: 1; scale: 1; }
    }
    &.is-flash { animation: mfm-flow-blink .34s steps(1, end) both; }
  }

  & .mfm-flow-field {
    position: relative; margin-top: 16px;
    &::after {
      content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; border-radius: 2px;
      background: var(--mfm-flow-accent); transform-origin: left; scale: 0 1;
      transition: scale .55s var(--mfm-flow-out), background-color .2s;
    }
    &:has(input:focus)::after { scale: 1 1; }
    &:has(input[aria-invalid="true"], input:user-invalid)::after { scale: 1 1; background: var(--mfm-flow-bad); }
  }
  & .mfm-flow-input {
    width: 100%; padding: 4px 0 9px; border: 0; border-bottom: 1.5px solid var(--mfm-flow-line); border-radius: 0;
    background: transparent; color: var(--mfm-flow-ink); caret-color: var(--mfm-flow-accent);
    font: 500 clamp(1.1rem, 0.8rem + 3.6cqi, 1.45rem)/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
    letter-spacing: -0.01em; outline: none;
    &::placeholder { color: color-mix(in oklch, var(--mfm-flow-ink) 28%, transparent); }
  }

  & .mfm-flow-err {
    display: flex; align-items: center; gap: 6px; min-height: 20px; margin: 10px 0 0;
    font-size: 12.5px; font-weight: 500; color: var(--mfm-flow-bad);
    opacity: 0; translate: 0 -4px; transition: opacity .2s, translate .35s var(--mfm-flow-out);
    & svg { width: 14px; height: 14px; }
    &.is-on { opacity: 1; translate: 0 0; }
  }

  & .mfm-flow-done { display: grid; gap: 4px; align-content: start; }
  & .mfm-flow-tick {
    width: 42px; height: 42px; margin-bottom: 8px; color: var(--mfm-flow-accent);
    & circle { stroke-width: 1.6; stroke-dasharray: 1; stroke-dashoffset: 1; animation: mfm-flow-draw .7s var(--mfm-flow-out) .05s forwards; }
    & path { stroke-width: 2.4; stroke-dasharray: 1; stroke-dashoffset: 1; animation: mfm-flow-draw .45s var(--mfm-flow-out) .45s forwards; }
  }
  & .mfm-flow-recap {
    display: grid; grid-template-columns: auto 1fr; gap: 0 14px; margin: 14px 0 0; padding: 4px 12px;
    border-radius: 12px; background: var(--mfm-flow-raise); border: 1px solid var(--mfm-flow-line); font-size: 13px;
    & > div {
      display: grid; grid-template-columns: subgrid; grid-column: 1 / -1; padding: 7px 0;
      animation: mfm-flow-rise .5s var(--mfm-flow-out) both; animation-delay: calc(var(--i) * 60ms + 380ms);
      & + div { border-top: 1px solid var(--mfm-flow-line); }
    }
    & dt { color: var(--mfm-flow-mute); }
    & dd { margin: 0; font-weight: 560; min-width: 0; overflow-wrap: anywhere; }
  }
  & .mfm-flow-again {
    justify-self: start; margin-top: 12px; padding: 0; border: 0; background: none;
    color: var(--mfm-flow-accent); font-weight: 600; font-size: 13px;
    text-decoration: underline 1px color-mix(in oklch, var(--mfm-flow-accent) 45%, transparent); text-underline-offset: 4px;
    &:hover { text-decoration-color: currentColor; }
  }

  & .mfm-flow-foot {
    grid-area: foot; display: flex; align-items: center; gap: 10px;
    padding-top: 12px; border-top: 1px solid var(--mfm-flow-line);
  }
  & .mfm-flow-back {
    width: 36px; height: 36px; display: grid; place-items: center; padding: 0;
    border-radius: 10px; border: 1px solid var(--mfm-flow-line); background: transparent;
    transition: background-color .2s, opacity .2s, transform .35s var(--mfm-flow-spring);
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: var(--mfm-flow-raise); }
    &:active:not(:disabled) { transform: scale(.92); }
    &:disabled { opacity: .3; cursor: default; }
  }
  & .mfm-flow-tip {
    margin: 0 auto 0 0; font-size: 12px; color: var(--mfm-flow-mute); white-space: nowrap;
    & kbd {
      display: inline-block; padding: 2px 5px; margin: 0 1px; border-radius: 5px;
      font: 600 10.5px/1.2 ui-monospace, Menlo, monospace; color: var(--mfm-flow-ink);
      border: 1px solid var(--mfm-flow-line); border-bottom-width: 2px;
    }
  }
  & .mfm-flow-ok {
    position: relative; display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 14px 0 16px;
    border: 0; border-radius: 10px; background: var(--mfm-flow-accent); color: var(--mfm-flow-bg);
    font-weight: 680; letter-spacing: .005em;
    box-shadow: 0 8px 22px -10px var(--mfm-flow-accent), inset 0 1px 0 color-mix(in oklch, white 45%, transparent);
    transition: filter .2s, transform .4s var(--mfm-flow-spring);
    & svg { width: 15px; height: 15px; stroke-width: 2.2; }
    &:hover { filter: brightness(1.06); }
    &:active { transform: scale(.95); }
    &[aria-busy="true"] { pointer-events: none; & svg { display: none; } & .mfm-flow-spin { display: block; } }
  }
  & .mfm-flow-spin {
    display: none; width: 14px; height: 14px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, var(--mfm-flow-bg) 30%, transparent); border-top-color: var(--mfm-flow-bg);
    animation: mfm-flow-spin .7s linear infinite;
  }

  &.is-done .mfm-flow-foot { display: none; }
  &.is-done .mfm-flow-track::after { box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-flow-accent) 22%, transparent); }

  @container (max-width: 300px) {
    & { padding: 14px 14px 12px; }
    & .mfm-flow-tip { display: none; }
    & .mfm-flow-foot { justify-content: space-between; }
  }
}

@supports (animation-timeline: scroll()) {
  .mfm-flow .mfm-flow-stage { animation: mfm-flow-edge linear both; animation-timeline: scroll(self); }
}

/* view transition: the stage is captured under a per-instance name carrying these classes */
::view-transition-group(*.mfm-flow-vt) { animation-duration: .5s; animation-timing-function: cubic-bezier(.16, 1, .3, 1); }
::view-transition-old(*.mfm-flow-fwd) { animation: mfm-flow-out-up .24s cubic-bezier(.5, 0, .75, 0) both; }
::view-transition-new(*.mfm-flow-fwd) { animation: mfm-flow-in-up .55s cubic-bezier(.16, 1, .3, 1) .06s both; }
::view-transition-old(*.mfm-flow-back) { animation: mfm-flow-out-down .24s cubic-bezier(.5, 0, .75, 0) both; }
::view-transition-new(*.mfm-flow-back) { animation: mfm-flow-in-down .55s cubic-bezier(.16, 1, .3, 1) .06s both; }

@keyframes mfm-flow-out-up { to { opacity: 0; transform: translateY(-16px); filter: blur(4px); } }
@keyframes mfm-flow-in-up { from { opacity: 0; transform: translateY(22px); filter: blur(4px); } }
@keyframes mfm-flow-out-down { to { opacity: 0; transform: translateY(16px); filter: blur(4px); } }
@keyframes mfm-flow-in-down { from { opacity: 0; transform: translateY(-22px); filter: blur(4px); } }
@keyframes mfm-flow-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes mfm-flow-blink { 0%, 50% { opacity: .45; } 25%, 75% { opacity: 1; } }
@keyframes mfm-flow-draw { to { stroke-dashoffset: 0; } }
@keyframes mfm-flow-tick { from { opacity: 0; transform: translateY(-60%); } }
@keyframes mfm-flow-spin { to { rotate: 1turn; } }
@keyframes mfm-flow-edge { 0%, 92% { --mfm-flow-fade: 22px; } 100% { --mfm-flow-fade: 0px; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-flow {
    transition: none;
    & .mfm-flow-opt, & .mfm-flow-recap > div, & .mfm-flow-count b { animation: none; }
    & .mfm-flow-opt.is-flash { animation: none; }
    & .mfm-flow-tick circle, & .mfm-flow-tick path { animation: none; stroke-dashoffset: 0; }
    & .mfm-flow-field::after, & .mfm-flow-err, & .mfm-flow-check { transition: opacity .15s; }
    & .mfm-flow-spin { animation-duration: 1.6s; }
  }
}

js:
const $ = s => root.querySelector(s);
const stage = $('[data-stage]'), bar = $('[data-bar]'), count = $('[data-count]');
const back = $('[data-back]'), ok = $('[data-ok]'), okLabel = $('[data-oklabel]'), tip = $('[data-tip]');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const uid = 'mfm-flow-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const ARROW = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10M9 4l4 4-4 4"/></svg>';
const CHECK = '<svg class="mfm-flow-check" viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7"/></svg>';
const ALERT = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="M8 4.8v3.6M8 11.1v.1"/></svg>';

/* the script: each question names the next one, so branches are just data */
const Q = {
  kind: { type: 'choice', title: () => 'What are we making together?',
    sub: 'Pick the closest fit — we refine scope together on a call.',
    opts: [['brand', 'Brand identity'], ['site', 'Marketing website'], ['product', 'Product UI'], ['unsure', 'Not sure yet']],
    next: v => v === 'brand' ? 'naming' : v === 'unsure' ? 'budget' : 'scope' },
  scope: { type: 'choice', title: () => 'Roughly how many screens or pages?',
    sub: 'A ballpark is plenty at this stage.',
    opts: [['s', 'Fewer than 10'], ['m', '10 to 30'], ['l', 'More than 30']], next: () => 'budget' },
  naming: { type: 'choice', title: () => 'Does the brand have a name yet?',
    sub: 'Naming adds about two weeks to the timeline.',
    opts: [['yes', 'Yes, it’s settled'], ['draft', 'A working title'], ['no', 'No — naming is in scope']], next: () => 'budget' },
  budget: { type: 'choice', title: () => 'What budget are you working with?',
    sub: 'Ranges in US dollars, before tax.',
    opts: [['a', '$8k – $15k'], ['b', '$15k – $40k'], ['c', '$40k and up']], next: () => 'name' },
  name: { type: 'text', title: () => 'Who should we address the proposal to?',
    sub: 'First name is plenty.', ph: 'Your name', ac: 'given-name', next: () => 'email' },
  email: { type: 'email', title: a => 'Thanks, ' + a.name + '. Where should we send it?',
    sub: 'We reply within two working days.', ph: 'name@company.com', ac: 'email', next: () => null }
};
const label = (id, v) => { const o = Q[id].opts.find(x => x[0] === v); return o ? o[1] : ''; };

let ans = {}, hist = ['kind'], done = false, busy = false, timer = 0, ptr = false;
const cur = () => hist[hist.length - 1];
const total = () => ans.kind === 'unsure' ? 4 : 5;

function questionHTML(id) {
  const q = Q[id], n = hist.length, t = esc(q.title(ans));
  let h = '<div class="mfm-flow-q" data-q="' + id + '"><p class="mfm-flow-qnum"><span>' + String(n).padStart(2, '0') + '</span>' + ARROW + '</p>';
  if (q.type === 'choice') {
    h += '<h3 class="mfm-flow-title" id="' + uid + '-t">' + t + '</h3><p class="mfm-flow-sub">' + esc(q.sub) + '</p>' +
      '<div class="mfm-flow-opts" role="radiogroup" aria-labelledby="' + uid + '-t" aria-describedby="' + uid + '-e">' +
      q.opts.map((o, i) => '<label class="mfm-flow-opt" style="--i:' + i + '"><input type="radio" name="' + uid + '-' + id +
        '" value="' + o[0] + '"' + (ans[id] === o[0] ? ' checked' : '') + '><kbd>' + 'ABCD'[i] + '</kbd><span>' + esc(o[1]) +
        '</span>' + CHECK + '</label>').join('') + '</div>';
  } else {
    h += '<label class="mfm-flow-title" id="' + uid + '-t" for="' + uid + '-in">' + t + '</label><p class="mfm-flow-sub">' + esc(q.sub) + '</p>' +
      '<div class="mfm-flow-field"><input class="mfm-flow-input" id="' + uid + '-in" type="' + q.type + '" required spellcheck="false" autocomplete="' +
      q.ac + '" placeholder="' + q.ph + '" aria-describedby="' + uid + '-e" value="' + esc(ans[id] || '') + '"></div>';
  }
  return h + '<p class="mfm-flow-err" id="' + uid + '-e" role="alert"></p></div>';
}

function doneHTML() {
  const scope = ans.kind === 'brand' ? label('naming', ans.naming) : ans.kind === 'unsure' ? 'To scope on our call' : label('scope', ans.scope);
  const what = ans.kind === 'unsure' ? 'project' : label('kind', ans.kind).toLowerCase();
  const rows = [['Project', label('kind', ans.kind)], ['Scope', scope], ['Budget', label('budget', ans.budget)], ['Reply to', ans.email]];
  return '<div class="mfm-flow-done"><svg class="mfm-flow-tick" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="21" pathLength="1"/>' +
    '<path d="m15.5 24.5 6 6 11.5-13" pathLength="1"/></svg><h3 class="mfm-flow-title" tabindex="-1">Brief received, ' + esc(ans.name) + '.</h3>' +
    '<p class="mfm-flow-sub">Expect a proposal for your ' + esc(what) + ' within two working days.</p><dl class="mfm-flow-recap">' +
    rows.map((r, i) => '<div style="--i:' + i + '"><dt>' + r[0] + '</dt><dd>' + esc(r[1]) + '</dd></div>').join('') +
    '</dl><button type="button" class="mfm-flow-again" data-restart>Start another brief</button></div>';
}

function sync() {
  const tot = total(), k = hist.length - 1, p = done ? 1 : k / tot;
  root.style.setProperty('--mfm-flow-p', p.toFixed(4));
  bar.setAttribute('aria-valuenow', String(Math.round(p * 100)));
  bar.setAttribute('aria-valuetext', done ? 'Complete' : 'Question ' + (k + 1) + ' of ' + tot);
  count.innerHTML = done ? '<b>Complete</b>' : '<b>' + String(k + 1).padStart(2, '0') + '</b> / ' + String(tot).padStart(2, '0');
  back.disabled = k === 0 || done || busy;
  root.classList.toggle('is-done', done);
  if (done) return;
  const q = Q[cur()];
  okLabel.textContent = cur() === 'email' ? 'Submit' : 'OK';
  tip.innerHTML = q.type === 'choice'
    ? 'Press <kbd>A</kbd>–<kbd>' + 'ABCD'[q.opts.length - 1] + '</kbd> or <kbd>Enter ↵</kbd>'
    : 'Press <kbd>Enter ↵</kbd>';
}

function focusStage() {
  const el = done ? stage.querySelector('.mfm-flow-title')
    : stage.querySelector('input:checked') || stage.querySelector('input');
  if (el) el.focus({ preventScroll: true });
}

function clearVT() { stage.style.removeProperty('view-transition-name'); stage.style.removeProperty('view-transition-class'); }

function show(dir, focus) {
  const update = () => { stage.innerHTML = done ? doneHTML() : questionHTML(cur()); stage.scrollTop = 0; sync(); if (focus) focusStage(); };
  if (RM.matches) { update(); return; }
  if (typeof document.startViewTransition === 'function') {
    stage.style.setProperty('view-transition-name', uid);
    stage.style.setProperty('view-transition-class', 'mfm-flow-vt mfm-flow-' + dir);
    let t;
    try { t = document.startViewTransition(update); } catch (e) { clearVT(); update(); return; }
    t.finished.then(clearVT, clearVT);
    return;
  }
  update();
  const y = dir === 'back' ? -16 : 16;
  stage.animate([{ opacity: 0, transform: 'translateY(' + y + 'px)', filter: 'blur(4px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
    { duration: 480, easing: 'cubic-bezier(.16,1,.3,1)' });
}

function fail(msg, inp) {
  const e = stage.querySelector('.mfm-flow-err');
  if (!e) return;
  e.innerHTML = ALERT + '<span>' + esc(msg) + '</span>';
  e.classList.add('is-on');
  const target = inp ? inp.closest('.mfm-flow-field') : stage.querySelector('.mfm-flow-opts');
  if (inp) { inp.setAttribute('aria-invalid', 'true'); inp.focus({ preventScroll: true }); }
  else { const r = stage.querySelector('input'); if (r) r.focus({ preventScroll: true }); }
  if (!RM.matches && target) target.animate(
    [{ transform: 'translateX(0)' }, { transform: 'translateX(-7px)' }, { transform: 'translateX(6px)' }, { transform: 'translateX(-3px)' }, { transform: 'translateX(0)' }],
    { duration: 380, easing: 'cubic-bezier(.36,.07,.19,.97)' });
}
function clearErr() {
  const e = stage.querySelector('.mfm-flow-err'); if (e) e.classList.remove('is-on');
  const i = stage.querySelector('input[aria-invalid]'); if (i) i.removeAttribute('aria-invalid');
}
function problem(id, v) {
  if (id === 'name') return v.length < 2 ? 'Add a name so we know who to address it to.' : '';
  if (id === 'email') return !v ? 'We need an email to send the proposal to.' : !EMAIL.test(v) ? 'That address looks incomplete — try name@company.com.' : '';
  return '';
}

function next() {
  if (busy || done) return;
  clearTimeout(timer);
  const id = cur(), q = Q[id];
  if (q.type === 'choice') {
    const c = stage.querySelector('input:checked');
    if (!c) return fail('Choose one of the options to continue.');
    ans[id] = c.value;
  } else {
    const inp = stage.querySelector('input'), v = inp.value.trim(), msg = problem(id, v);
    if (msg) return fail(msg, inp);
    ans[id] = v;
  }
  const nx = q.next(ans[id]);
  if (nx) { hist.push(nx); show('fwd', true); return; }
  busy = true; ok.setAttribute('aria-busy', 'true'); okLabel.textContent = 'Sending'; back.disabled = true;
  timer = setTimeout(() => {
    if (!root.isConnected) return;
    busy = false; done = true; ok.removeAttribute('aria-busy');
    show('fwd', true);
  }, 950);
}

function prev() {
  if (busy || done || hist.length < 2) return;
  clearTimeout(timer);
  const id = cur(), inp = stage.querySelector('.mfm-flow-input');
  if (inp) ans[id] = inp.value.trim();
  hist.pop();
  show('back', true);
}

function pick(inp) {
  inp.checked = true;
  inp.focus({ preventScroll: true });
  clearErr();
  const opt = inp.closest('.mfm-flow-opt');
  if (!RM.matches) { opt.classList.remove('is-flash'); void opt.offsetWidth; opt.classList.add('is-flash'); }
  clearTimeout(timer);
  timer = setTimeout(() => { if (!root.isConnected) return; if (stage.contains(inp) && inp.checked) next(); }, RM.matches ? 140 : 420);
}

root.addEventListener('submit', e => { e.preventDefault(); next(); });
back.addEventListener('click', prev);
root.addEventListener('pointerdown', e => { ptr = !!e.target.closest('.mfm-flow-opt'); });
stage.addEventListener('click', e => {
  if (e.target.closest('[data-restart]')) {
    ans = {}; hist = ['kind']; done = false; show('back', true); return;
  }
  const inp = e.target.closest('input[type="radio"]');
  if (inp && ptr) { ptr = false; pick(inp); }
});
stage.addEventListener('change', e => { if (e.target.type === 'radio') clearErr(); });
stage.addEventListener('input', e => {
  const inp = e.target;
  if (inp.getAttribute('aria-invalid') === 'true' && !problem(cur(), inp.value.trim())) clearErr();
});
root.addEventListener('keydown', e => {
  ptr = false;
  if (e.key === 'Enter' && !e.isComposing) {
    if (e.target.closest('button')) return;
    e.preventDefault(); next(); return;
  }
  if (done || busy || e.altKey || e.ctrlKey || e.metaKey || e.key.length !== 1) return;
  const q = Q[cur()];
  if (q.type !== 'choice' || e.target.matches('.mfm-flow-input')) return;
  const i = 'abcd'.indexOf(e.key.toLowerCase());
  const inp = i < 0 ? null : stage.querySelectorAll('input[type="radio"]')[i];
  if (inp) { e.preventDefault(); pick(inp); }
});

stage.innerHTML = questionHTML(cur());
sync();

css:
.mfm-people {
  /* re-theme with these four */
  --mfm-people-bg: oklch(0.992 0.003 250);
  --mfm-people-ink: oklch(0.24 0.022 262);
  --mfm-people-accent: oklch(0.53 0.17 258);
  --mfm-people-bad: oklch(0.56 0.19 27);

  --mfm-people-mute: color-mix(in oklch, var(--mfm-people-ink) 54%, var(--mfm-people-bg));
  --mfm-people-line: color-mix(in oklch, var(--mfm-people-ink) 12%, transparent);
  --mfm-people-soft: color-mix(in oklch, var(--mfm-people-ink) 4%, var(--mfm-people-bg));
  --mfm-people-tint: color-mix(in oklch, var(--mfm-people-accent) 10%, var(--mfm-people-bg));
  --mfm-people-ring: color-mix(in oklch, var(--mfm-people-accent) 22%, transparent);
  --mfm-people-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-people-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 400px; min-height: 418px;
  display: grid; align-content: start; gap: 16px;
  padding: 16px; border-radius: 16px;
  background: var(--mfm-people-bg); color: var(--mfm-people-ink);
  box-shadow: 0 1px 0 color-mix(in oklch, white 70%, transparent) inset, 0 24px 48px -24px oklch(0 0 0 / .55);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-people-accent); outline-offset: 2px; }

  & .mfm-people-doc {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 11px;
    padding: 10px 12px 10px 10px; border-radius: 12px; background: var(--mfm-people-soft); border: 1px solid var(--mfm-people-line);
  }
  & .mfm-people-docicon {
    width: 34px; height: 34px; display: grid; place-items: center; border-radius: 9px;
    background: var(--mfm-people-tint); color: var(--mfm-people-accent);
    & svg { width: 18px; height: 18px; }
  }
  & .mfm-people-doctext {
    display: grid; min-width: 0;
    & b { font-size: 13.5px; font-weight: 640; letter-spacing: -0.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & span { font-size: 12px; color: var(--mfm-people-mute); }
  }
  & .mfm-people-owner {
    width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center;
    border: 1.5px dashed color-mix(in oklch, var(--mfm-people-ink) 26%, transparent);
    &.is-set { border: 0; animation: mfm-people-pop .55s var(--mfm-people-spring); }
    & .mfm-people-av { width: 28px; height: 28px; font-size: 10.5px; }
  }

  & .mfm-people-field { position: relative; z-index: 3; display: grid; gap: 6px; }
  & .mfm-people-label {
    font-size: 12.5px; font-weight: 600; letter-spacing: .01em;
    & i { font-style: normal; font-weight: 450; color: var(--mfm-people-mute); }
  }
  & .mfm-people-anchor { position: relative; }
  & .mfm-people-box {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 8px;
    height: 44px; padding: 0 5px 0 11px; border-radius: 12px; background: white;
    border: 1px solid color-mix(in oklch, var(--mfm-people-ink) 18%, transparent);
    box-shadow: 0 1px 2px oklch(0 0 0 / .05);
    transition: border-color .2s, box-shadow .25s;
    &:hover { border-color: color-mix(in oklch, var(--mfm-people-ink) 30%, transparent); }
    &:focus-within { border-color: var(--mfm-people-accent); box-shadow: 0 0 0 4px var(--mfm-people-ring); }
    & input {
      min-width: 0; height: 100%; border: 0; outline: 0; background: transparent; padding: 0;
      font: 500 14px/1 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--mfm-people-ink);
      &::placeholder { color: color-mix(in oklch, var(--mfm-people-ink) 40%, transparent); font-weight: 400; }
    }
  }
  & .mfm-people-lead {
    width: 24px; height: 24px; display: grid; place-items: center; color: var(--mfm-people-mute);
    & svg { width: 16px; height: 16px; }
    & .mfm-people-av { width: 24px; height: 24px; font-size: 9.5px; animation: mfm-people-pop .5s var(--mfm-people-spring); }
  }
  & .mfm-people-clear, & .mfm-people-toggle {
    width: 30px; height: 30px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 8px;
    background: transparent; color: var(--mfm-people-mute); transition: background-color .15s, color .15s;
    & svg { width: 16px; height: 16px; }
    &:hover { background: var(--mfm-people-soft); color: var(--mfm-people-ink); }
    &[hidden] { display: none; }
  }
  & .mfm-people-toggle svg { transition: rotate .35s var(--mfm-people-out); }
  &.is-open .mfm-people-toggle svg { rotate: 180deg; }

  & .mfm-people-help { margin: 0; font-size: 12px; color: var(--mfm-people-mute); text-wrap: pretty; min-height: 17px; }
  &.is-error {
    & .mfm-people-box { border-color: var(--mfm-people-bad); box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-people-bad) 16%, transparent); }
    & .mfm-people-help { color: var(--mfm-people-bad); font-weight: 500; }
  }

  /* the popup: an absolutely positioned layer inside the component */
  & .mfm-people-pop {
    position: absolute; left: 0; right: 0; top: calc(100% + 6px); z-index: 5;
    border-radius: 14px; background: white; border: 1px solid var(--mfm-people-line);
    box-shadow: 0 1px 2px oklch(0 0 0 / .06), 0 20px 40px -12px color-mix(in oklch, var(--mfm-people-ink) 35%, transparent);
    transform-origin: 50% 0; opacity: 0; visibility: hidden; translate: 0 -6px; scale: .985;
    clip-path: inset(0 0 100% 0 round 14px);
    transition: opacity .16s ease-in, translate .2s ease-in, scale .2s ease-in, clip-path .2s ease-in, visibility 0s linear .2s;
  }
  &.is-open .mfm-people-pop {
    opacity: 1; visibility: visible; translate: 0 0; scale: 1; clip-path: inset(0 0 0 0 round 14px);
    transition: opacity .2s ease-out, translate .45s var(--mfm-people-out), scale .45s var(--mfm-people-out), clip-path .42s var(--mfm-people-out), visibility 0s;
  }
  & .mfm-people-scroll {
    position: relative; max-height: 212px; overflow-y: auto; overscroll-behavior: contain; padding: 5px;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--mfm-people-ink) 20%, transparent) transparent;
  }
  & .mfm-people-hl {
    position: absolute; left: 5px; right: 5px; top: 0; height: 0; border-radius: 9px; pointer-events: none;
    background: var(--mfm-people-tint); opacity: 0;
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-people-accent) 22%, transparent);
    transition: translate .42s var(--mfm-people-spring), height .3s var(--mfm-people-out), opacity .15s;
    &.is-on { opacity: 1; }
    &.is-jump { transition: opacity .15s; }
  }
  & .mfm-people-group {
    & + .mfm-people-group { margin-top: 4px; }
  }
  & .mfm-people-gh {
    padding: 8px 9px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase;
    color: var(--mfm-people-mute);
  }
  & .mfm-people-opt {
    position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 10px;
    min-height: 46px; padding: 6px 9px; border-radius: 9px; cursor: pointer;
    &.is-stagger { animation: mfm-people-in .4s var(--mfm-people-out) both; animation-delay: calc(var(--i) * 26ms); }
    & b { display: block; font-size: 13.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { display: block; font-size: 12px; color: var(--mfm-people-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & mark {
      background: none; color: var(--mfm-people-accent); font-weight: 700;
      text-decoration: underline 2px color-mix(in oklch, var(--mfm-people-accent) 35%, transparent); text-underline-offset: 3px;
    }
    &[aria-selected="true"] .mfm-people-tickmark { opacity: 1; scale: 1; }
    &[aria-disabled="true"] { cursor: not-allowed; & .mfm-people-av, & b { opacity: .45; } }
  }
  & .mfm-people-tickmark {
    position: absolute; right: 9px; top: 50%; margin-top: -8px; width: 16px; height: 16px; color: var(--mfm-people-accent);
    opacity: 0; scale: .5; transition: opacity .2s, scale .4s var(--mfm-people-spring);
  }
  & .mfm-people-opt[aria-selected="true"] .mfm-people-st { visibility: hidden; }
  & .mfm-people-av {
    width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;
    font: 650 11px/1 system-ui, -apple-system, sans-serif; letter-spacing: .02em;
    background: oklch(0.9 0.06 var(--h)); color: oklch(0.38 0.1 var(--h));
    box-shadow: inset 0 0 0 1px oklch(0.5 0.08 var(--h) / .18);
  }
  & .mfm-people-st {
    display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; color: var(--mfm-people-mute); white-space: nowrap;
    &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: oklch(0.72 0.15 150); }
    &.is-busy::before { background: oklch(0.78 0.15 75); }
    &.is-away::before { background: color-mix(in oklch, var(--mfm-people-ink) 28%, transparent); }
  }
  & .mfm-people-empty {
    display: grid; justify-items: center; gap: 4px; padding: 22px 16px 20px; text-align: center;
    animation: mfm-people-in .35s var(--mfm-people-out) both;
    & svg { width: 26px; height: 26px; color: color-mix(in oklch, var(--mfm-people-ink) 35%, transparent); margin-bottom: 4px; }
    & b { font-size: 13.5px; font-weight: 620; overflow-wrap: anywhere; }
    & span { font-size: 12px; color: var(--mfm-people-mute); text-wrap: balance; }
  }
  & .mfm-people-skel {
    display: grid; grid-template-columns: 30px 1fr; gap: 10px; align-items: center; padding: 8px 9px;
    & i, & s {
      display: block; border-radius: 99px;
      background: linear-gradient(90deg, var(--mfm-people-soft) 30%, color-mix(in oklch, var(--mfm-people-ink) 9%, transparent) 50%, var(--mfm-people-soft) 70%) 0 0 / 300% 100%;
      animation: mfm-people-shimmer 1.1s linear infinite;
    }
    & i { width: 30px; height: 30px; }
    & s { height: 9px; width: calc(48% + var(--i) * 9%); }
  }
  & .mfm-people-meta {
    display: flex; justify-content: space-between; gap: 8px; margin: 0; padding: 7px 12px;
    border-top: 1px solid var(--mfm-people-line); font-size: 11.5px; color: var(--mfm-people-mute);
    font-variant-numeric: tabular-nums;
    & kbd { font: 600 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; border: 1px solid var(--mfm-people-line); color: var(--mfm-people-ink); }
    & .is-bad { color: var(--mfm-people-bad); font-weight: 550; }
  }

  & .mfm-people-recent {
    display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
    & > span { font-size: 12px; color: var(--mfm-people-mute); }
  }
  & .mfm-people-chips { display: flex; gap: 6px; flex-wrap: wrap; }
  & .mfm-people-chip {
    display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px 0 3px; border-radius: 99px;
    border: 1px solid var(--mfm-people-line); background: white; font-size: 12.5px; font-weight: 550;
    transition: border-color .2s, background-color .2s, transform .35s var(--mfm-people-spring);
    & .mfm-people-av { width: 22px; height: 22px; font-size: 9px; }
    &:hover { border-color: color-mix(in oklch, var(--mfm-people-accent) 40%, transparent); background: var(--mfm-people-tint); }
    &:active { transform: scale(.95); }
    &[aria-pressed="true"] { border-color: var(--mfm-people-accent); background: var(--mfm-people-tint); color: var(--mfm-people-accent); }
  }

  & .mfm-people-msg {
    display: grid; gap: 6px;
    & textarea {
      resize: none; width: 100%; padding: 9px 11px; border-radius: 12px; background: white;
      border: 1px solid color-mix(in oklch, var(--mfm-people-ink) 18%, transparent);
      font: 400 13.5px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--mfm-people-ink);
      transition: border-color .2s, box-shadow .25s;
      &::placeholder { color: color-mix(in oklch, var(--mfm-people-ink) 40%, transparent); }
      &:focus { outline: none; border-color: var(--mfm-people-accent); box-shadow: 0 0 0 4px var(--mfm-people-ring); }
    }
  }

  & .mfm-people-foot {
    display: flex; align-items: center; justify-content: space-between; gap: 12px;
    padding-top: 14px; border-top: 1px solid var(--mfm-people-line); margin-top: auto;
  }
  & .mfm-people-note {
    min-width: 0; font-size: 12.5px; color: var(--mfm-people-mute); text-wrap: pretty;
    & b { color: var(--mfm-people-ink); font-weight: 600; }
  }
  & .mfm-people-assign {
    flex: none; display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 16px; border: 0; border-radius: 10px;
    background: var(--mfm-people-accent); color: white; font-weight: 620; font-size: 13.5px;
    box-shadow: 0 1px 0 color-mix(in oklch, white 30%, transparent) inset, 0 6px 16px -8px var(--mfm-people-accent);
    transition: background-color .2s, color .2s, box-shadow .2s, transform .35s var(--mfm-people-spring);
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mfm-people-accent), black 10%); }
    &:active:not(:disabled) { transform: scale(.95); }
    &:disabled { background: var(--mfm-people-soft); color: color-mix(in oklch, var(--mfm-people-ink) 38%, transparent); box-shadow: inset 0 0 0 1px var(--mfm-people-line); cursor: not-allowed; }
    &[aria-busy="true"] { pointer-events: none; & .mfm-people-spin { display: block; } }
    &.is-done, &.is-done:hover:not(:disabled) { background: oklch(0.95 0.045 150); color: oklch(0.42 0.1 150); box-shadow: inset 0 0 0 1px oklch(0.82 0.08 150); cursor: default; transform: none; }
  }
  & .mfm-people-spin {
    display: none; width: 13px; height: 13px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, white 35%, transparent); border-top-color: white;
    animation: mfm-people-spin .7s linear infinite;
  }
  & .mfm-people-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

  @container (max-width: 290px) {
    & { padding: 14px; gap: 14px; }
    & .mfm-people-st { font-size: 0; gap: 0; }
    & .mfm-people-opt { grid-template-columns: 30px minmax(0, 1fr) auto; }
    & .mfm-people-meta [data-hint] { display: none; }
  }
}

@keyframes mfm-people-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes mfm-people-pop { from { scale: .4; opacity: 0; } }
@keyframes mfm-people-shimmer { to { background-position: -150% 0; } }
@keyframes mfm-people-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-people {
    & .mfm-people-pop, &.is-open .mfm-people-pop { translate: none; scale: none; clip-path: none; transition: opacity .12s, visibility 0s; }
    & .mfm-people-hl { transition: opacity .12s; }
    & .mfm-people-opt.is-stagger, & .mfm-people-empty, & .mfm-people-lead .mfm-people-av, & .mfm-people-owner.is-set { animation: none; }
    & .mfm-people-skel i, & .mfm-people-skel s { animation: none; }
    & .mfm-people-toggle svg { transition: none; }
  }
}

