const $ = s => root.querySelector(s);
const input = $('[data-input]'), list = $('[data-list]'), scroller = $('[data-scroll]'), hl = $('[data-hl]');
const meta = $('[data-meta]'), help = $('[data-help]'), lead = $('[data-lead]'), clearBtn = $('[data-clear]');
const toggle = $('[data-toggle]'), owner = $('[data-owner]'), note = $('[data-note]'), live = $('[data-live]');
const assign = $('[data-assign]'), assignLabel = $('[data-assignlabel]'), recent = $('[data-recent]');
const field = $('.mfm-people-field'), lbl = $('[data-label]'), pop = $('[data-pop]');
const uid = 'mfm-people-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const SEARCH = '<svg viewBox="0 0 16 16"><circle cx="7" cy="7" r="4.75"/><path d="m10.6 10.6 3.4 3.4"/></svg>';
const TICK = '<svg class="mfm-people-tickmark" viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7"/></svg>';
const HELP = help.textContent;

const TEAMS = ['Design', 'Engineering', 'Research'];
const P = [
  { id: 'maya', name: 'Maya Okafor', role: 'Product designer', handle: 'maya', team: 'Design', h: 28 },
  { id: 'theo', name: 'Theo Lindqvist', role: 'Design lead', handle: 'theo', team: 'Design', h: 250 },
  { id: 'ines', name: 'Inês Carvalho', role: 'Brand designer', handle: 'ines', team: 'Design', h: 340, st: 'away', note: 'Away till Oct 14' },
  { id: 'ravi', name: 'Ravi Menon', role: 'Staff engineer', handle: 'ravi.m', team: 'Engineering', h: 160 },
  { id: 'jun', name: 'Jun Park', role: 'Frontend engineer', handle: 'jun', team: 'Engineering', h: 205 },
  { id: 'sofia', name: 'Sofia Brandt', role: 'iOS engineer', handle: 'sofia', team: 'Engineering', h: 62, st: 'busy', note: 'Focus till 3pm' },
  { id: 'marcus', name: 'Marcus Hale', role: 'Platform engineer', handle: 'mhale', team: 'Engineering', h: 120 },
  { id: 'adaeze', name: 'Adaeze Nwosu', role: 'UX researcher', handle: 'adaeze', team: 'Research', h: 300 },
  { id: 'lena', name: 'Lena Fischer', role: 'Research ops', handle: 'lena.f', team: 'Research', h: 95 }
];
P.forEach(p => { p.first = p.name.split(' ')[0]; p.ini = p.name.split(' ').map(w => w[0]).join(''); });
const byId = id => P.find(p => p.id === id);
const av = p => '<span class="mfm-people-av" style="--h:' + p.h + '">' + esc(p.ini) + '</span>';

/* ids + ARIA wiring */
input.id = uid + '-in'; lbl.htmlFor = input.id; list.id = uid + '-list'; help.id = uid + '-help';
input.setAttribute('aria-controls', list.id); input.setAttribute('aria-describedby', help.id);

let isOpen = false, loaded = false, active = -1, els = [], chosen = null, assigned = null, loadT = 0, sayT = 0;

