function optHTML(p, i, m, stagger) {
  const handle = '@' + p.handle;
  const st = p.st ? '<span class="mfm-people-st is-' + p.st + '">' + esc(p.note) + '</span>' : '<span></span>';
  return '<div role="option" class="mfm-people-opt' + (stagger ? ' is-stagger' : '') + '" id="' + uid + '-' + p.id + '" data-id="' + p.id +
    '" aria-selected="' + (chosen === p) + '"' + (p.st === 'away' ? ' aria-disabled="true"' : '') + ' style="--i:' + i + '">' + av(p) +
