recent.innerHTML = ['maya', 'ravi', 'adaeze'].map(id => { const p = byId(id); return '<button type="button" class="mfm-people-chip" data-id="' + id + '" aria-pressed="false">' + av(p) + esc(p.first) + '</button>'; }).join('');
recent.addEventListener('click', e => { const b = e.target.closest('button'); if (b) choose(byId(b.dataset.id)); });

assign.addEventListener('click', () => {
  if (!chosen || assign.getAttribute('aria-disabled') === 'true' || assign.getAttribute('aria-busy') === 'true') return;
  const p = chosen;
  assign.setAttribute('aria-busy', 'true'); assignLabel.textContent = 'Assigning';
  setTimeout(() => {
    if (!root.isConnected) return;
    assign.removeAttribute('aria-busy');
    assigned = p;
    owner.innerHTML = av(p); owner.classList.remove('is-set'); void owner.offsetWidth; owner.classList.add('is-set');
