unchoose();

css:
.mfm-invite {
  /* re-theme with these five */
  --mfm-invite-bg: oklch(0.2 0.017 158);
  --mfm-invite-ink: oklch(0.95 0.014 140);
  --mfm-invite-accent: oklch(0.88 0.17 126);
  --mfm-invite-guest: oklch(0.84 0.12 78);
  --mfm-invite-bad: oklch(0.71 0.18 24);

  --mfm-invite-mute: color-mix(in oklch, var(--mfm-invite-ink) 55%, var(--mfm-invite-bg));
  --mfm-invite-line: color-mix(in oklch, var(--mfm-invite-ink) 12%, transparent);
  --mfm-invite-raise: color-mix(in oklch, var(--mfm-invite-ink) 5%, var(--mfm-invite-bg));
  --mfm-invite-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-invite-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; overflow: clip; box-sizing: border-box;
  width: 100%; max-width: 420px;
  display: grid; gap: 14px; padding: 16px 16px 15px;
  border-radius: 18px; border: 1px solid var(--mfm-invite-line);
  background:
    radial-gradient(90% 60% at 0% 0%, color-mix(in oklch, var(--mfm-invite-accent) 9%, transparent), transparent 70%),
    var(--mfm-invite-bg);
  color: var(--mfm-invite-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-invite-accent); outline-offset: 2px; }

  & .mfm-invite-head {
    & h3 { margin: 0; font-size: clamp(1rem, 0.8rem + 2.4cqi, 1.18rem); font-weight: 650; letter-spacing: -0.015em; text-wrap: balance; }
    & p { margin: 4px 0 0; font-size: 12.5px; color: var(--mfm-invite-mute); text-wrap: pretty; }
    & b { color: var(--mfm-invite-accent); font-weight: 600; font-family: ui-monospace, Menlo, monospace; font-size: 12px; }
  }

  & .mfm-invite-group { display: grid; gap: 7px; }
  & .mfm-invite-label { font-size: 12.5px; font-weight: 600; }
  & .mfm-invite-field {
    display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
    min-height: 46px; max-height: 136px; overflow-y: auto; padding: 7px; border-radius: 13px; cursor: text;
    background: color-mix(in oklch, var(--mfm-invite-bg), black 22%);
    border: 1px solid color-mix(in oklch, var(--mfm-invite-ink) 16%, transparent);
    scrollbar-width: thin; scrollbar-color: var(--mfm-invite-line) transparent;
    transition: border-color .2s, box-shadow .25s;
    &:focus-within { border-color: color-mix(in oklch, var(--mfm-invite-accent) 70%, transparent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-invite-accent) 14%, transparent); }
    & input {
      flex: 1 0 9ch; min-width: 9ch; height: 30px; padding: 0 4px; border: 0; outline: 0; background: transparent;
      font: 400 13.5px/1 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--mfm-invite-ink);
      &::placeholder { color: color-mix(in oklch, var(--mfm-invite-ink) 34%, transparent); }
    }
  }
  & .mfm-invite-chips { display: contents; }

  & .mfm-invite-chip {
    --mfm-invite-c: var(--mfm-invite-accent);
    display: inline-flex; align-items: center; gap: 5px; max-width: 100%; height: 28px; padding: 0 2px 0 3px; border-radius: 99px;
    background: color-mix(in oklch, var(--mfm-invite-c) 13%, transparent);
    border: 1px solid color-mix(in oklch, var(--mfm-invite-c) 38%, transparent);
    font-size: 12px; font-weight: 520; outline: none; cursor: default;
    transition: scale .45s var(--mfm-invite-spring), opacity .2s, filter .3s, background-color .2s, box-shadow .2s;
    @starting-style { scale: .55; opacity: 0; filter: blur(4px); }
    &:focus-visible { box-shadow: 0 0 0 2px var(--mfm-invite-bg), 0 0 0 4px var(--mfm-invite-c); background: color-mix(in oklch, var(--mfm-invite-c) 24%, transparent); }
    &.is-guest { --mfm-invite-c: var(--mfm-invite-guest); }
    &.is-bad {
      --mfm-invite-c: var(--mfm-invite-bad);
      background: transparent; border-style: dashed;
      & .mfm-invite-em { color: var(--mfm-invite-bad); text-decoration: underline wavy 1px color-mix(in oklch, var(--mfm-invite-bad) 70%, transparent); text-underline-offset: 3px; }
    }
    &.is-nudge { animation: mfm-invite-nudge .45s cubic-bezier(.36, .07, .19, .97); }
  }
  & .mfm-invite-av {
    width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%;
    background: var(--mfm-invite-c); color: var(--mfm-invite-bg);
    font: 700 10.5px/1 system-ui, -apple-system, sans-serif; text-transform: uppercase;
    & svg { width: 12px; height: 12px; stroke-width: 2.4; }
  }
  & .mfm-invite-em { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .mfm-invite-tag {
    padding: 2px 5px; border-radius: 5px; font: 650 9px/1.1 system-ui, -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase;
    color: var(--mfm-invite-bg); background: var(--mfm-invite-guest);
  }
  & .mfm-invite-x {
    width: 22px; height: 22px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 50%;
    background: transparent; color: color-mix(in oklch, var(--mfm-invite-ink) 60%, transparent);
    transition: background-color .15s, color .15s;
    & svg { width: 12px; height: 12px; stroke-width: 2; }
    &:hover { background: color-mix(in oklch, var(--mfm-invite-c) 28%, transparent); color: var(--mfm-invite-ink); }
  }

  & .mfm-invite-msg {
    display: flex; gap: 6px; align-items: flex-start; margin: -2px 0 0; min-height: 18px;
    font-size: 12px; color: var(--mfm-invite-mute); text-wrap: pretty;
    & kbd { font: 600 10.5px/1.3 ui-monospace, Menlo, monospace; padding: 0 4px; border-radius: 4px; border: 1px solid var(--mfm-invite-line); color: var(--mfm-invite-ink); }
    & svg { width: 14px; height: 14px; margin-top: 1px; }
    &.is-bad { color: var(--mfm-invite-bad); font-weight: 500; }
  }

  & .mfm-invite-sugg {
    display: flex; align-items: center; gap: 8px; flex-wrap: wrap; min-height: 28px;
    & > span { font-size: 12px; color: var(--mfm-invite-mute); }
    & > div { display: flex; flex-wrap: wrap; gap: 6px; }
  }
  & .mfm-invite-pill {
    display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 10px 0 7px; border-radius: 99px;
    border: 1px dashed color-mix(in oklch, var(--mfm-invite-ink) 22%, transparent); background: transparent;
    font-size: 12px; font-weight: 520; color: color-mix(in oklch, var(--mfm-invite-ink) 82%, transparent);
    transition: border-color .2s, background-color .2s, color .2s, scale .4s var(--mfm-invite-spring), opacity .2s;
    & svg { width: 12px; height: 12px; stroke-width: 2; color: var(--mfm-invite-accent); }
    &.is-guest svg { color: var(--mfm-invite-guest); }
    &:hover { border-style: solid; border-color: color-mix(in oklch, var(--mfm-invite-accent) 50%, transparent); background: color-mix(in oklch, var(--mfm-invite-accent) 8%, transparent); color: var(--mfm-invite-ink); }
    &:active { scale: .94; }
    @starting-style { scale: .7; opacity: 0; }
  }
  & .mfm-invite-none { font-size: 12px; color: color-mix(in oklch, var(--mfm-invite-ink) 38%, transparent); font-style: italic; }

  & .mfm-invite-seats {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 6px 12px;
    padding-top: 13px; border-top: 1px solid var(--mfm-invite-line);
    & small { grid-column: 1 / -1; font-size: 12px; color: var(--mfm-invite-mute); text-wrap: pretty; }
    & b { font: 600 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap; }
  }
  & .mfm-invite-seatlabel { font-size: 12.5px; font-weight: 600; }
  & .mfm-invite-meter {
    display: grid; grid-template-columns: repeat(var(--mfm-invite-n, 10), minmax(0, 1fr)); gap: 3px; height: 9px;
    & i {
      border-radius: 2.5px; background: color-mix(in oklch, var(--mfm-invite-ink) 11%, transparent);
      transform-origin: 50% 100%; transition: background-color .3s;
      &.is-used { background: color-mix(in oklch, var(--mfm-invite-accent) 42%, var(--mfm-invite-bg)); }
      &.is-new { background: var(--mfm-invite-accent); box-shadow: 0 0 10px color-mix(in oklch, var(--mfm-invite-accent) 55%, transparent); animation: mfm-invite-seat .55s var(--mfm-invite-spring) both; }
      &.is-over {
        background: repeating-linear-gradient(-45deg, var(--mfm-invite-bad) 0 3px, color-mix(in oklch, var(--mfm-invite-bad) 45%, transparent) 3px 6px);
        animation: mfm-invite-seat .55s var(--mfm-invite-spring) both;
      }
    }
  }
  &.is-over {
    & .mfm-invite-seats b, & .mfm-invite-seats small { color: var(--mfm-invite-bad); }
  }

  & .mfm-invite-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
  & .mfm-invite-sum { min-width: 0; font-size: 12.5px; color: var(--mfm-invite-mute); font-variant-numeric: tabular-nums; & b { color: var(--mfm-invite-ink); font-weight: 600; } }
  & .mfm-invite-send {
    flex: none; display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 15px 0 16px; border: 0; border-radius: 11px;
    background: var(--mfm-invite-accent); color: var(--mfm-invite-bg); font-weight: 680; font-size: 13.5px;
    box-shadow: 0 10px 24px -12px var(--mfm-invite-accent), inset 0 1px 0 color-mix(in oklch, white 50%, transparent);
    transition: filter .2s, transform .4s var(--mfm-invite-spring), background-color .2s, color .2s, box-shadow .2s;
    & svg { width: 15px; height: 15px; stroke-width: 1.9; transition: translate .4s var(--mfm-invite-spring); }
    &:hover:not(:disabled) { filter: brightness(1.06); & svg { translate: 2px -2px; } }
    &:active:not(:disabled) { transform: scale(.95); }
    &:disabled { background: var(--mfm-invite-raise); color: color-mix(in oklch, var(--mfm-invite-ink) 36%, transparent); box-shadow: inset 0 0 0 1px var(--mfm-invite-line); cursor: not-allowed; }
    &[aria-busy="true"] { pointer-events: none; & svg { display: none; } & .mfm-invite-spin { display: block; } }
  }
  & .mfm-invite-spin {
    display: none; width: 14px; height: 14px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, var(--mfm-invite-bg) 30%, transparent); border-top-color: var(--mfm-invite-bg);
    animation: mfm-invite-spin .7s linear infinite;
  }

  & .mfm-invite-toast {
    position: absolute; left: 14px; right: 14px; bottom: 14px; z-index: 4;
    display: flex; align-items: center; gap: 10px; padding: 11px 13px; border-radius: 12px;
    background: var(--mfm-invite-ink); color: var(--mfm-invite-bg); font-size: 13px; font-weight: 550;
    box-shadow: 0 18px 40px -12px oklch(0 0 0 / .6);
    opacity: 0; translate: 0 130%; pointer-events: none;
    transition: translate .5s var(--mfm-invite-spring), opacity .2s;
    & svg { width: 18px; height: 18px; color: oklch(0.55 0.15 140); stroke-width: 2.2; }
    &.is-on { opacity: 1; translate: 0 0; }
  }
  & .mfm-invite-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

  @container (max-width: 290px) {
    & { padding: 15px; gap: 14px; }
    & .mfm-invite-foot { flex-wrap: wrap; }
    & .mfm-invite-sugg {
      flex-wrap: nowrap; & > span { display: none; }
      & > div { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; margin: 0 -15px; padding: 0 15px; scroll-padding-inline: 15px;
        mask-image: linear-gradient(90deg, transparent, #000 15px, #000 calc(100% - 22px), transparent); }
    }
    & .mfm-invite-pill { flex: none; }
    & .mfm-invite-send { flex: 1; justify-content: center; }
    & .mfm-invite-sum { flex-basis: 100%; }
  }
}

@keyframes mfm-invite-seat { from { scale: 1 .2; opacity: .3; } }
@keyframes mfm-invite-nudge { 0%, 100% { translate: 0; } 20% { translate: -5px; } 40% { translate: 4px; } 60% { translate: -3px; } 80% { translate: 2px; } }
@keyframes mfm-invite-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-invite {
    & .mfm-invite-chip, & .mfm-invite-pill { transition: background-color .15s, box-shadow .15s; @starting-style { scale: 1; opacity: 1; filter: none; } }
    & .mfm-invite-chip.is-nudge { animation: none; box-shadow: 0 0 0 2px var(--mfm-invite-bg), 0 0 0 4px var(--mfm-invite-c); }
    & .mfm-invite-meter i { animation: none !important; }
    & .mfm-invite-toast { translate: 0 0; transition: opacity .2s; }
    & .mfm-invite-send svg { transition: none; }
  }
}

js:
const $ = s => root.querySelector(s);
const field = $('[data-field]'), box = $('[data-chips]'), input = $('[data-input]'), msg = $('[data-msg]'), lbl = $('[data-label]');
const sugg = $('[data-sugg]'), meter = $('[data-meter]'), seatNum = $('[data-seatnum]'), seatNote = $('[data-seatnote]');
const sum = $('[data-sum]'), send = $('[data-send]'), sendLabel = $('[data-sendlabel]'), toast = $('[data-toast]'), live = $('[data-live]');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1)';
const uid = 'mfm-invite-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const X = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4.5 4.5 7 7M11.5 4.5l-7 7"/></svg>';
const BANG = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.5v5.5M8 12.2v.1"/></svg>';
const PLUS = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.5v9M3.5 8h9"/></svg>';
const ALERT = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="M8 4.8v3.6M8 11.1v.1"/></svg>';
const HINT = '<kbd>Enter</kbd> or <kbd>,</kbd> adds an address — or paste a list.';

const DOMAIN = 'quarry.dev', SEATS = 10;
const EMAIL = /^[^\s@<>(),;:"]+@[^\s@<>(),;:"]+\.[a-z]{2,}$/i;
const SUGG = [['Odile Brandt', 'odile@quarry.dev'], ['Kenji Mori', 'kenji.mori@quarry.dev'], ['Ruth Achebe', 'ruth@lumenpress.org']];
let base = 6, chips = [], busy = false, toastT = 0;

input.id = uid + '-in'; lbl.htmlFor = input.id; msg.id = uid + '-msg';
input.setAttribute('aria-describedby', msg.id);

const kindOf = e => !EMAIL.test(e) ? 'bad' : e.toLowerCase().endsWith('@' + DOMAIN) ? 'member' : 'guest';
function why(e) {
  if (!e.includes('@')) return 'is missing an @';
  if (/@[^.]*$/.test(e)) return 'needs a domain ending like .com';
  return 'isn’t a valid address';
}
function say(m) { live.textContent = ''; setTimeout(() => { if (root.isConnected) live.textContent = m; }, 30); }

function chipEl(c) {
  const el = document.createElement('span');
  el.className = 'mfm-invite-chip is-' + c.kind;
  el.setAttribute('role', 'listitem');
  el.tabIndex = -1;
  const k = c.kind === 'bad' ? 'invalid, ' + why(c.email) : c.kind;
  el.setAttribute('aria-label', c.email + ', ' + k + '. Backspace removes, Enter edits.');
  el.innerHTML = '<span class="mfm-invite-av" aria-hidden="true">' + (c.kind === 'bad' ? BANG : esc(c.email[0])) + '</span>' +
    '<span class="mfm-invite-em">' + esc(c.email) + '</span>' + (c.kind === 'guest' ? '<span class="mfm-invite-tag" aria-hidden="true">Guest</span>' : '') +
    '<button type="button" class="mfm-invite-x" tabindex="-1" aria-label="Remove ' + esc(c.email) + '">' + X + '</button>';
  if (c.kind === 'bad') el.title = c.email + ' ' + why(c.email);
  el._chip = c;
  return el;
}

function add(raw) {
  let e = String(raw).trim();
  const angle = e.match(/<([^>]+)>/);
  if (angle) e = angle[1];
  e = e.replace(/^mailto:/i, '').replace(/^[<("']+|[>)"'.,;]+$/g, '').trim();
  if (!e) return 'skip';
  const dup = chips.find(c => c.email.toLowerCase() === e.toLowerCase());
  if (dup) {
    dup.el.classList.remove('is-nudge'); void dup.el.offsetWidth; dup.el.classList.add('is-nudge');
    return 'dup';
  }
  const c = { email: e, kind: kindOf(e) };
  c.el = chipEl(c);
  box.append(c.el);
  chips.push(c);
  return 'ok';
}

function commit(text) {
  const parts = String(text).split(/[,;\n]+/).flatMap(s => /<[^>]+>/.test(s) ? [s] : s.trim().split(/\s+/)).filter(Boolean);
  let ok = 0, dup = 0;
  parts.forEach(p => { const r = add(p); if (r === 'ok') ok++; else if (r === 'dup') dup++; });
  if (ok || dup) {
    input.value = '';
    update();
    field.scrollTop = field.scrollHeight;
    if (parts.length > 1 || dup) say('Added ' + ok + (ok === 1 ? ' address' : ' addresses') + (dup ? ', skipped ' + dup + ' already on the list' : ''));
    else say('Added ' + chips[chips.length - 1].email + ' as ' + (chips[chips.length - 1].kind === 'bad' ? 'an invalid address' : 'a ' + chips[chips.length - 1].kind));
  }
  return ok + dup;
}

/* FLIP: measure every chip (and the input), mutate, then play each one back from where it was */
function flip(mutate) {
  const nodes = [...box.children, input];
  const first = new Map(nodes.map(n => [n, n.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  first.forEach((r, n) => {
    if (!n.isConnected) return;
    const r2 = n.getBoundingClientRect(), dx = r.left - r2.left, dy = r.top - r2.top;
    if (Math.abs(dx) + Math.abs(dy) > 0.5) n.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: SPRING });
  });
}

function remove(c, focusTo) {
  const i = chips.indexOf(c);
  if (i < 0) return;
  chips.splice(i, 1);
  update();
  const target = focusTo === 'prev' ? (chips[i - 1] || chips[i]) : focusTo === 'next' ? chips[i] : null;
  if (target) target.el.focus(); else input.focus();
  say('Removed ' + c.email);
  const gone = () => flip(() => c.el.remove());
  if (RM.matches) { gone(); return; }
  c.el.style.pointerEvents = 'none';
  c.el.animate([{ opacity: 1, transform: 'scale(1)', filter: 'blur(0)' }, { opacity: 0, transform: 'scale(.6)', filter: 'blur(3px)' }],
    { duration: 170, easing: 'cubic-bezier(.4,0,1,1)', fill: 'forwards' }).finished.then(gone, gone);
}

function edit(c) {
  const pending = input.value.trim();
  remove(c, null);
  input.value = c.email + (pending ? ', ' + pending : '');
  input.focus();
  input.setSelectionRange(c.email.length, c.email.length);
}

function update() {
  const m = chips.filter(c => c.kind === 'member').length, g = chips.filter(c => c.kind === 'guest').length;
  const bad = chips.filter(c => c.kind === 'bad');
  const used = base + m, over = Math.max(0, used - SEATS), n = Math.max(SEATS, used);

  /* seat meter — keep the nodes, so only segments that change state animate */
  if (meter.children.length !== n) {
    meter.style.setProperty('--mfm-invite-n', n);
    meter.innerHTML = Array.from({ length: n }, () => '<i></i>').join('');
  }
  [...meter.children].forEach((s, i) => {
    const cls = i < base ? 'is-used' : i < used ? (i < SEATS ? 'is-new' : 'is-over') : '';
    if (s.className !== cls) s.className = cls;
  });
  seatNum.textContent = Math.min(used, 99) + ' of ' + SEATS;
  const left = SEATS - used;
  seatNote.textContent = over
    ? over + ' over the Team plan — remove ' + (over === 1 ? 'a member' : over + ' members') + ' or upgrade to Business.'
    : base + ' in use' + (m ? ' + ' + m + ' pending' : '') + ' · ' + left + ' left · guests are free';
  root.classList.toggle('is-over', over > 0);

  if (bad.length) {
    msg.className = 'mfm-invite-msg is-bad';
    msg.innerHTML = ALERT + '<span>' + (bad.length === 1 ? esc(bad[0].email) + ' ' + why(bad[0].email) : bad.length + ' addresses need fixing') + ' — select it and press <kbd>Enter</kbd> to edit.</span>';
  } else { msg.className = 'mfm-invite-msg'; msg.innerHTML = '<span>' + HINT + '</span>'; }

  sum.innerHTML = chips.length
    ? '<b>' + m + '</b> ' + (m === 1 ? 'member' : 'members') + ' · <b>' + g + '</b> ' + (g === 1 ? 'guest' : 'guests') + (bad.length ? ' · <b>' + bad.length + '</b> to fix' : '')
    : 'No one added yet';
  sendLabel.textContent = chips.length ? 'Send ' + chips.length + (chips.length === 1 ? ' invite' : ' invites') : 'Send invites';
  send.disabled = busy || !chips.length || bad.length > 0 || over > 0;
  input.placeholder = chips.length ? 'Add another…' : 'name@company.com';

  const have = new Set(chips.map(c => c.email.toLowerCase()));
  const open = SUGG.filter(s => !have.has(s[1]));
  const current = [...sugg.querySelectorAll('button')].map(b => b.dataset.email).join();
  if (current !== open.map(s => s[1]).join()) {
    sugg.innerHTML = open.length ? open.map(s => '<button type="button" class="mfm-invite-pill' + (kindOf(s[1]) === 'guest' ? ' is-guest' : '') + '" data-email="' + s[1] +
      '" title="' + s[1] + '" aria-label="Add ' + s[0] + ', ' + s[1] + '">' + PLUS + esc(s[0]) + '</button>').join('')
      : '<span class="mfm-invite-none">Everyone suggested is on the list</span>';
  }
}

field.addEventListener('pointerdown', e => {
  if (e.target === field || e.target === box) { e.preventDefault(); input.focus(); }
});
input.addEventListener('keydown', e => {
  const v = input.value;
  if ((e.key === 'Enter' || e.key === ',' || e.key === ';') && v.trim()) { e.preventDefault(); commit(v); }
  else if (e.key === 'Enter') e.preventDefault();
  else if (e.key === ' ' && v.includes('@') && !v.includes('<')) { e.preventDefault(); commit(v); }
  else if (e.key === 'Tab' && v.trim() && !e.shiftKey) { e.preventDefault(); commit(v); }
  else if ((e.key === 'Backspace' || e.key === 'ArrowLeft') && input.selectionStart === 0 && input.selectionEnd === 0 && chips.length) {
    e.preventDefault(); chips[chips.length - 1].el.focus();
  }
});
input.addEventListener('paste', e => {
  const t = (e.clipboardData || window.clipboardData).getData('text');
  if (!t || !/[,;\s]/.test(t.trim())) return;
  e.preventDefault(); commit(input.value + ' ' + t);
});
input.addEventListener('blur', () => { if (input.value.trim() && !busy) commit(input.value); });

box.addEventListener('keydown', e => {
  const el = e.target.closest('.mfm-invite-chip'); if (!el) return;
  const c = el._chip, i = chips.indexOf(c);
  if (e.key === 'ArrowLeft') { e.preventDefault(); (chips[i - 1] || c).el.focus(); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); chips[i + 1] ? chips[i + 1].el.focus() : input.focus(); }
  else if (e.key === 'Home') { e.preventDefault(); chips[0].el.focus(); }
  else if (e.key === 'End') { e.preventDefault(); input.focus(); }
  else if (e.key === 'Backspace') { e.preventDefault(); remove(c, i > 0 ? 'prev' : 'next'); }
  else if (e.key === 'Delete') { e.preventDefault(); remove(c, 'next'); }
  else if (e.key === 'Enter' || e.key === 'F2') { e.preventDefault(); edit(c); }
  else if (e.key === 'Escape') { e.preventDefault(); input.focus(); }
  else if (e.key.length === 1 && !e.metaKey && !e.ctrlKey) input.focus();
});
box.addEventListener('click', e => {
  const x = e.target.closest('.mfm-invite-x'), el = e.target.closest('.mfm-invite-chip');
  if (x && el) { remove(el._chip, null); return; }
  if (el) el.focus();
});
box.addEventListener('dblclick', e => { const el = e.target.closest('.mfm-invite-chip'); if (el) edit(el._chip); });
sugg.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  commit(b.dataset.email); input.focus();
});

send.addEventListener('click', () => {
  if (send.disabled || busy) return;
  busy = true; send.setAttribute('aria-busy', 'true'); sendLabel.textContent = 'Sending';
  setTimeout(() => {
    if (!root.isConnected) return;
    const sent = chips.slice(), n = sent.length, m = sent.filter(c => c.kind === 'member').length;
    const finish = () => {
      if (!root.isConnected) return;
      sent.forEach(c => c.el.remove());
      chips = []; base += m; busy = false; send.removeAttribute('aria-busy');
      update();
      toast.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9.25"/><path d="m8 12.5 2.8 2.8L16.5 9"/></svg><span>' + n + (n === 1 ? ' invite' : ' invites') + ' sent' +
        (m ? ' · ' + m + (m === 1 ? ' seat' : ' seats') + ' reserved' : '') + '</span>';
      toast.classList.add('is-on'); say(toast.textContent);
      clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) toast.classList.remove('is-on'); }, 3200);
    };
    if (RM.matches) { finish(); return; }
    sent.forEach((c, i) => c.el.animate([{ opacity: 1, transform: 'none', filter: 'blur(0)' }, { opacity: 0, transform: 'translateY(-16px) scale(.92)', filter: 'blur(3px)' }],
      { duration: 340, delay: i * 45, easing: 'cubic-bezier(.4,0,.2,1)', fill: 'forwards' }));
    setTimeout(finish, n * 45 + 360);
  }, 900);
});

['ana.reyes@quarry.dev', 'joel@fieldnotes.co'].forEach(add);
update();

css:
.mfm-record {
  /* re-theme with these four */
  --mfm-record-bg: oklch(0.985 0.006 88);
  --mfm-record-ink: oklch(0.24 0.018 70);
  --mfm-record-accent: oklch(0.5 0.105 152);
  --mfm-record-bad: oklch(0.55 0.19 27);

  --mfm-record-mute: color-mix(in oklch, var(--mfm-record-ink) 55%, var(--mfm-record-bg));
  --mfm-record-line: color-mix(in oklch, var(--mfm-record-ink) 10%, transparent);
  --mfm-record-soft: color-mix(in oklch, var(--mfm-record-ink) 4.5%, var(--mfm-record-bg));
  --mfm-record-tint: color-mix(in oklch, var(--mfm-record-accent) 13%, var(--mfm-record-bg));
  --mfm-record-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-record-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px;
  display: grid; gap: 14px; padding: 16px 18px 14px;
  border-radius: 16px; background: var(--mfm-record-bg); color: var(--mfm-record-ink);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-record-ink) 8%, transparent), 0 24px 48px -26px oklch(0 0 0 / .55);
  font: 400 14px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-record-accent); outline-offset: 2px; }

  & .mfm-record-head { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; }
  & .mfm-record-mono {
    width: 40px; height: 40px; display: grid; place-items: center; border-radius: 11px;
    background: var(--mfm-record-accent); color: var(--mfm-record-bg);
    font: 700 14px/1 ui-serif, Georgia, serif; letter-spacing: .02em;
    box-shadow: inset 0 -2px 0 color-mix(in oklch, black 18%, transparent);
  }
  & .mfm-record-title {
    min-width: 0;
    & h3 { margin: 0; font-size: clamp(1rem, .8rem + 2.2cqi, 1.14rem); font-weight: 680; letter-spacing: -0.015em; text-wrap: balance; }
    & p { margin: 1px 0 0; font-size: 12px; color: var(--mfm-record-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .mfm-record-pill {
    display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 9px; border-radius: 99px;
    background: var(--mfm-record-tint); color: color-mix(in oklch, var(--mfm-record-accent), black 18%);
    font-size: 11.5px; font-weight: 650;
    &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  }

  & .mfm-record-rows {
    display: grid; grid-template-columns: minmax(84px, 31%) minmax(0, 1fr) 18px; column-gap: 12px; margin: 0;
    border-bottom: 1px solid var(--mfm-record-line);
  }
  & .mfm-record-row {
    position: relative; display: grid; grid-template-columns: subgrid; grid-column: 1 / -1; align-items: center;
    min-height: 40px; padding: 2px 0; border-top: 1px solid var(--mfm-record-line);
    & dt { font-size: 12.5px; color: var(--mfm-record-mute); font-weight: 500; }
    & dd { margin: 0; min-width: 0; }
    &.is-editing { align-items: start; & dt { padding-top: 9px; } & .mfm-record-st { margin-top: 10px; } }
  }

  /* read mode and edit mode share the same box metrics, so the text never moves */
  & .mfm-record-val, & .mfm-record-in {
    width: calc(100% + 16px); margin: 0 -8px; height: 32px; padding: 0 8px; border-radius: 8px;
