    & .mfm-record-pen { width: 14px; height: 14px; margin-left: auto; color: var(--mfm-record-mute); opacity: 0; translate: -4px 0; transition: opacity .15s, translate .3s var(--mfm-record-out); }
    &:hover, &:focus-visible { background: var(--mfm-record-soft); border-color: var(--mfm-record-line); & .mfm-record-pen { opacity: 1; translate: 0 0; } }
    &.is-empty .mfm-record-txt { color: var(--mfm-record-mute); font-weight: 450; font-style: italic; }
    &.is-empty .mfm-record-pen { opacity: .7; translate: 0 0; }
    &.is-flash .mfm-record-txt { animation: mfm-record-flash 1.6s var(--mfm-record-out); }
    &[aria-disabled="true"] {
