  }
  & .mfm-record-tip {
    position: absolute; z-index: 3; right: 22px; bottom: calc(100% - 6px); padding: 6px 9px; border-radius: 7px;
    background: var(--mfm-record-ink); color: var(--mfm-record-bg); font-size: 11.5px; font-weight: 500; white-space: nowrap;
    opacity: 0; translate: 0 4px; pointer-events: none; transition: opacity .15s, translate .25s var(--mfm-record-out);
  }
  & .mfm-record-row:has([aria-disabled="true"]:hover, [aria-disabled="true"]:focus-visible) .mfm-record-tip,
  & .mfm-record-row.is-tip .mfm-record-tip { opacity: 1; translate: 0 0; }

  & .mfm-record-edit {
    display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "in ok no" "err err err"; align-items: center; column-gap: 4px;
    padding: 4px 0;
  }
  & .mfm-record-wrap { grid-area: in; position: relative; min-width: 0; display: flex; align-items: center; }
  & .mfm-record-in {
    border: 1px solid var(--mfm-record-accent); background: white; outline: none;
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--mfm-record-accent) 18%, transparent);
    animation: mfm-record-open .3s var(--mfm-record-out);
    &[aria-invalid="true"] { border-color: var(--mfm-record-bad); box-shadow: 0 0 0 3px color-mix(in oklch, var(--mfm-record-bad) 16%, transparent); }
    &.is-money { padding-left: 21px; }
  }
  & select.mfm-record-in { appearance: none; padding-right: 26px; cursor: pointer; }
  & .mfm-record-caret { position: absolute; right: 2px; width: 14px; height: 14px; pointer-events: none; color: var(--mfm-record-mute); }
  & .mfm-record-pre { position: absolute; left: 1px; font-size: 13.5px; color: var(--mfm-record-mute); pointer-events: none; z-index: 1; }
  & .mfm-record-ok, & .mfm-record-no {
