  }
  & .mfm-record-entry {
    display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; column-gap: 9px; align-items: start; padding: 6px 0;
    font-size: 12.5px; line-height: 1.35;
    & + .mfm-record-entry { border-top: 1px dashed var(--mfm-record-line); }
    &.is-new { animation: mfm-record-enter .5s var(--mfm-record-out) both; }
    & p { margin: 0; }
    & b { font-weight: 620; }
    & s { color: var(--mfm-record-mute); text-decoration-color: color-mix(in oklch, var(--mfm-record-bad) 60%, transparent); }
    & ins { text-decoration: none; font-weight: 560; color: color-mix(in oklch, var(--mfm-record-accent), black 22%); }
  }
  & .mfm-record-etext { min-width: 0; }
