  }
  & .mfm-record-who {
    width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; margin-top: 1px;
    font: 650 9px/1 system-ui, -apple-system, sans-serif; background: oklch(0.92 0.04 var(--h, 70)); color: oklch(0.4 0.08 var(--h, 70));
    &.is-you { background: var(--mfm-record-accent); color: white; }
  }
  & .mfm-record-undo {
    height: 22px; padding: 0 8px; border-radius: 6px; border: 1px solid var(--mfm-record-line); background: white;
    font-size: 11.5px; font-weight: 600; color: var(--mfm-record-ink); display: inline-flex; align-items: center; gap: 4px;
    transition: background-color .15s, border-color .15s;
    & svg { width: 12px; height: 12px; }
    &:hover { border-color: color-mix(in oklch, var(--mfm-record-ink) 25%, transparent); background: var(--mfm-record-soft); }
  }
  & .mfm-record-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

  @container (max-width: 280px) {
    & { padding: 14px; gap: 12px; }
    & .mfm-record-rows { grid-template-columns: minmax(0, 1fr) 18px; }
    & .mfm-record-row {
      grid-template-columns: subgrid; row-gap: 0; min-height: 0; padding: 5px 0 1px;
      & dt { grid-column: 1 / -1; font-size: 11px; line-height: 1.15; }
      &.is-editing dt { padding-top: 0; }
      &.is-editing .mfm-record-st { margin-top: 8px; }
    }
    & .mfm-record-val, & .mfm-record-in { height: 27px; font-size: 13px; }
    & .mfm-record-pill { display: none; }
    & .mfm-record-mono { width: 36px; height: 36px; }
    & .mfm-record-log { max-height: 88px; }
  }
}

@supports (animation-timeline: scroll()) {
  .mfm-record .mfm-record-log { animation: mfm-record-edge linear both; animation-timeline: scroll(self); }
}

@property --mfm-record-fade { syntax: '<length>'; inherits: false; initial-value: 0px; }
@keyframes mfm-record-edge { 0%, 90% { --mfm-record-fade: 20px; } 100% { --mfm-record-fade: 0px; } }
@keyframes mfm-record-flash { 0%, 20% { background: color-mix(in oklch, var(--mfm-record-accent) 26%, transparent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--mfm-record-accent) 26%, transparent); } }
@keyframes mfm-record-open { from { box-shadow: 0 0 0 0 transparent; } }
@keyframes mfm-record-spin { to { rotate: 1turn; } }
@keyframes mfm-record-saved { 0% { opacity: 0; scale: .4; } 15% { opacity: 1; scale: 1; } 80% { opacity: 1; } 100% { opacity: 0; } }
@keyframes mfm-record-enter { from { opacity: 0; translate: 0 -6px; } }
@keyframes mfm-record-wiggle { 0%, 100% { rotate: 0deg; } 25% { rotate: -14deg; } 50% { rotate: 10deg; } 75% { rotate: -5deg; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-record {
    & .mfm-record-in, & .mfm-record-entry.is-new, & .mfm-record-val.is-shake .mfm-record-pen { animation: none; }
    & .mfm-record-val.is-flash .mfm-record-txt { animation-duration: .01s; }
    & .mfm-record-st.is-saved { animation: none; opacity: 1; }
    & .mfm-record-val .mfm-record-pen, & .mfm-record-tip { transition: opacity .15s; translate: none; }
  }
}

js:
const $ = s => root.querySelector(s);
const rows = $('[data-rows]'), logEl = $('[data-log]'), sub = $('[data-sub]'), count = $('[data-count]'), live = $('[data-live]');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const doc = root.ownerDocument;
const uid = 'mfm-record-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const ICON = {
  pen: '<svg class="mfm-record-pen" viewBox="0 0 16 16" aria-hidden="true"><path d="M10.5 3.2 12.8 5.5 6 12.3l-3 .7.7-3Z"/><path d="m9.3 4.4 2.3 2.3"/></svg>',
  plus: '<svg class="mfm-record-pen" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.5v9M3.5 8h9"/></svg>',
  lock: '<svg class="mfm-record-pen" viewBox="0 0 16 16" aria-hidden="true"><rect x="3.5" y="7" width="9" height="6.5" rx="1.5"/><path d="M5.5 7V5.2a2.5 2.5 0 0 1 5 0V7"/></svg>',
  ok: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7"/></svg>',
  no: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4.5 4.5 7 7M11.5 4.5l-7 7"/></svg>',
  caret: '<svg class="mfm-record-caret" viewBox="0 0 16 16" aria-hidden="true"><path d="m4.5 6.5 3.5 3.5 3.5-3.5"/></svg>',
  undo: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M5.5 4 2.5 7l3 3"/><path d="M2.5 7h7a4 4 0 0 1 0 8h-2"/></svg>'
};

const F = [
  { k: 'legal', label: 'Legal name', type: 'text', v: 'Halden Supply Co. Ltd', req: true, ac: 'organization' },
  { k: 'contact', label: 'Contact', type: 'text', v: 'Priya Raman', req: true, ac: 'name' },
  { k: 'email', label: 'AP email', type: 'email', v: 'ap@haldensupply.co', req: true, ac: 'email' },
  { k: 'phone', label: 'Phone', type: 'tel', v: '', empty: 'Add phone number', ac: 'tel' },
  { k: 'terms', label: 'Payment terms', type: 'select', v: 'Net 30', opts: ['Net 15', 'Net 30', 'Net 45', 'Net 60'] },
  { k: 'limit', label: 'Credit limit', type: 'money', v: 25000 },
  { k: 'vid', label: 'Vendor ID', type: 'locked', v: 'HS-20417', why: 'Set by Finance — read only' }
];
const byK = k => F.find(f => f.k === k);
const money = n => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const show = f => f.type === 'money' ? money(f.v) : f.v;
const parseMoney = s => { const t = String(s).replace(/[$,\s]/g, ''); return /^\d+(\.\d{0,2})?$/.test(t) ? Math.round(parseFloat(t) * 100) / 100 : NaN; };

/* the activity log; entries made here can be undone while the field still holds their value */
let log = [
  { who: 'Grace Liu', ini: 'GL', h: 25, k: 'email', from: 'accounts@haldensupply.co', to: 'ap@haldensupply.co', at: 'Sep 18' },
  { who: 'Tomás Ruiz', ini: 'TR', h: 230, k: 'limit', from: 15000, to: 25000, at: 'Aug 2' }
];
let editing = null, seq = 0;

function say(m) { live.textContent = ''; setTimeout(() => { if (root.isConnected) live.textContent = m; }, 30); }

function valHTML(f) {
  if (f.type === 'locked') {
    return '<button type="button" class="mfm-record-val" aria-disabled="true" data-locked aria-describedby="' + uid + '-tip">' +
      '<span class="mfm-record-txt">' + esc(f.v) + '</span>' + ICON.lock + '</button><span class="mfm-record-tip" role="tooltip" id="' + uid + '-tip">' + esc(f.why) + '</span>';
  }
  const empty = f.v === '' || f.v == null;
  return '<button type="button" class="mfm-record-val' + (empty ? ' is-empty' : '') + '" data-open aria-label="' + esc(f.label) + ': ' +
    esc(empty ? 'empty' : show(f)) + '. Edit">' + '<span class="mfm-record-txt">' + esc(empty ? f.empty : show(f)) + '</span>' + (empty ? ICON.plus : ICON.pen) + '</button>';
}
function rowHTML(f, i) {
  return '<div class="mfm-record-row" data-k="' + f.k + '" style="--i:' + i + '"><dt id="' + uid + '-' + f.k + '">' + esc(f.label) + '</dt>' +
    '<dd data-cell>' + valHTML(f) + '</dd><span class="mfm-record-st" data-st aria-hidden="true"></span></div>';
}
const rowOf = k => rows.querySelector('[data-k="' + k + '"]');

function editorHTML(f) {
  const id = uid + '-in-' + f.k, err = uid + '-err-' + f.k;
  const common = ' id="' + id + '" class="mfm-record-in' + (f.type === 'money' ? ' is-money' : '') + '" aria-labelledby="' + uid + '-' + f.k + '" aria-describedby="' + err + '"';
  let ctl;
  if (f.type === 'select') {
    ctl = '<select' + common + '>' + f.opts.map(o => '<option' + (o === f.v ? ' selected' : '') + '>' + o + '</option>').join('') + '</select>' + ICON.caret;
  } else {
    const val = f.type === 'money' ? f.v.toLocaleString('en-US', { maximumFractionDigits: 2 }) : f.v;
    const type = f.type === 'money' ? 'text" inputmode="decimal' : f.type;
    ctl = (f.type === 'money' ? '<span class="mfm-record-pre" aria-hidden="true">$</span>' : '') +
      '<input' + common + ' type="' + type + '" value="' + esc(val) + '" spellcheck="false"' + (f.ac ? ' autocomplete="' + f.ac + '"' : ' autocomplete="off"') +
      (f.req ? ' required' : '') + (f.empty ? ' placeholder="' + esc(f.empty) + '"' : '') + '>';
  }
  return '<form class="mfm-record-edit" novalidate data-edit="' + f.k + '"><div class="mfm-record-wrap">' + ctl + '</div>' +
    '<button type="submit" class="mfm-record-ok" aria-label="Save ' + esc(f.label) + '">' + ICON.ok + '</button>' +
    '<button type="button" class="mfm-record-no" data-cancel aria-label="Cancel">' + ICON.no + '</button>' +
    '<p class="mfm-record-err" id="' + err + '" role="alert"></p></form>';
}

function renderRow(f, flash) {
  const row = rowOf(f.k);
  row.classList.remove('is-editing');
  row.querySelector('[data-cell]').innerHTML = valHTML(f);
  if (flash && !RM.matches) row.querySelector('.mfm-record-val').classList.add('is-flash');
}
function focusVal(k) { const b = rowOf(k).querySelector('.mfm-record-val'); if (b) b.focus({ preventScroll: true }); }
function setStatus(k, st) {
  const el = rowOf(k).querySelector('[data-st]');
  el.className = 'mfm-record-st' + (st ? ' is-' + st : '');
  el.innerHTML = st === 'saved' ? ICON.ok : '';
}
function syncSub() { sub.textContent = 'Vendor since 2021 · ' + byK('terms').v; }

function validate(f, raw) {
  if (f.req && !raw) return 'Required — it prints on every purchase order.';
  if (f.type === 'email' && raw && !EMAIL.test(raw)) return 'Use a full address, like ap@company.com.';
  if (f.type === 'tel' && raw && raw.replace(/\D/g, '').length < 7) return 'Include the area code — at least 7 digits.';
  if (f.type === 'money') {
    const n = parseMoney(raw);
    if (!raw || isNaN(n)) return 'Enter an amount, like 25,000.';
    if (n <= 0) return 'Must be more than $0.';
    if (n > 100000) return 'Over your $100,000 approval limit — ask Finance to raise it.';
  }
  return '';
}
const parse = (f, raw) => f.type === 'money' ? parseMoney(raw) : f.type === 'tel' ? raw.replace(/\s+/g, ' ') : raw;

function openEditor(k) {
  if (editing && editing.k === k) return;
  if (editing && !commit(false)) return;
  const f = byK(k), row = rowOf(k);
  editing = f;
  row.classList.add('is-editing');
  row.querySelector('[data-cell]').innerHTML = editorHTML(f);
  const inp = row.querySelector('.mfm-record-in');
  inp.focus({ preventScroll: true });
  if (inp.select && f.type !== 'select' && inp.value) inp.select();
}
function showErr(f, msg) {
  const row = rowOf(f.k), inp = row.querySelector('.mfm-record-in'), err = row.querySelector('.mfm-record-err');
  err.textContent = msg; inp.setAttribute('aria-invalid', 'true');
  if (!RM.matches) inp.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-5px)' }, { transform: 'translateX(4px)' }, { transform: 'translateX(-2px)' }, { transform: 'translateX(0)' }],
    { duration: 340, easing: 'cubic-bezier(.36,.07,.19,.97)' });
}
function commit(restore) {
  const f = editing;
  if (!f) return true;
  const row = rowOf(f.k), inp = row.querySelector('.mfm-record-in'), raw = inp.value.trim(), msg = validate(f, raw);
  if (msg) { showErr(f, msg); if (restore || doc.activeElement === doc.body) inp.focus({ preventScroll: true }); return false; }
  const val = parse(f, raw), old = f.v;
  editing = null;
  if (val === old) { renderRow(f); if (restore) focusVal(f.k); return true; }
  f.v = val;
  renderRow(f, false); setStatus(f.k, 'saving'); if (restore) focusVal(f.k);
  if (f.k === 'terms') syncSub();
  const id = ++seq;
  setTimeout(() => {
    if (!root.isConnected) return;
    setStatus(f.k, 'saved');
    const b = rowOf(f.k).querySelector('.mfm-record-val');
    if (b && !RM.matches) { b.classList.remove('is-flash'); void b.offsetWidth; b.classList.add('is-flash'); }
    addLog({ who: 'You', you: true, k: f.k, from: old, to: val, at: Date.now(), id });
    say(f.label + ' saved');
    setTimeout(() => { if (root.isConnected && rowOf(f.k).querySelector('[data-st]').classList.contains('is-saved')) setStatus(f.k, ''); }, 2300);
  }, 560 + (id % 3) * 120);
  return true;
}
function cancel() {
  const f = editing; if (!f) return;
  editing = null; renderRow(f); focusVal(f.k);
}

/* activity */
const fmt = (k, v) => k === 'limit' ? money(v) : v;
function ago(t) {
  if (typeof t === 'string') return t;
  const s = (Date.now() - t) / 1000;
  return s < 45 ? 'just now' : s < 3600 ? Math.round(s / 60) + ' min ago' : Math.round(s / 3600) + ' h ago';
}
function entryHTML(e, fresh) {
  const f = byK(e.k), from = fmt(e.k, e.from), to = fmt(e.k, e.to);
  const verb = (from === '' ? 'added ' : to === '' ? 'cleared ' : 'changed ') + '<b>' + esc(f.label) + '</b>';
  const diff = from === '' ? '<ins>' + esc(to) + '</ins>' : to === '' ? '<s>' + esc(from) + '</s>'
    : '<s>' + esc(from) + '</s> <span aria-label="to">→</span> <ins>' + esc(to) + '</ins>';
  const latest = log.find(x => x.k === e.k) === e;
  const undo = e.you && latest && f.v === e.to ? '<button type="button" class="mfm-record-undo" data-undo="' + e.id + '" aria-label="Undo ' + esc(f.label) + ' change">' + ICON.undo + 'Undo</button>' : '';
  return '<li class="mfm-record-entry' + (fresh ? ' is-new' : '') + '" data-id="' + (e.id || '') + '"><span class="mfm-record-who' + (e.you ? ' is-you' : '') + '" style="--h:' + (e.h || 150) + '" aria-hidden="true">' +
    (e.you ? 'You' : e.ini) + '</span><div class="mfm-record-etext"><p><b>' + esc(e.who) + '</b> ' + verb + '</p><p class="mfm-record-diff">' + diff + '</p></div>' +
    '<div class="mfm-record-eside"><time>' + ago(e.at) + '</time>' + undo + '</div></li>';
}
function renderLog(freshId) {
  const before = new Map([...logEl.children].map(n => [n.dataset.id || n.textContent, n.getBoundingClientRect().top]));
  logEl.innerHTML = log.map(e => entryHTML(e, freshId && e.id === freshId)).join('');
  count.textContent = log.length + (log.length === 1 ? ' change' : ' changes');
  if (RM.matches || !before.size) return;
  [...logEl.children].forEach(n => {
    const t = before.get(n.dataset.id || n.textContent);
    if (t == null) return;
    const dy = t - n.getBoundingClientRect().top;
    if (Math.abs(dy) > .5) n.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.16,1,.3,1)' });
  });
}
function addLog(e) { log.unshift(e); renderLog(e.id); logEl.scrollTop = 0; }

function undo(id) {
  const e = log.find(x => x.id === id); if (!e) return;
  const f = byK(e.k);
  if (editing === f) { editing = null; }
  f.v = e.from;
  renderRow(f, true); setStatus(f.k, '');
  if (f.k === 'terms') syncSub();
  const li = logEl.querySelector('[data-id="' + id + '"]');
  const finish = () => { log = log.filter(x => x !== e); renderLog(); };
  say(f.label + ' restored to ' + (fmt(e.k, e.from) || 'empty'));
  if (!li || RM.matches) { finish(); return; }
  li.animate([{ opacity: 1, height: li.offsetHeight + 'px' }, { opacity: 0, height: '0px', paddingTop: '0px', paddingBottom: '0px' }],
    { duration: 260, easing: 'cubic-bezier(.4,0,.2,1)', fill: 'forwards' }).finished.then(finish, finish);
}

/* events, all delegated to the root */
root.addEventListener('click', e => {
  const open = e.target.closest('[data-open]');
  if (open) { openEditor(open.closest('[data-k]').dataset.k); return; }
  if (e.target.closest('[data-cancel]')) { cancel(); return; }
  const lock = e.target.closest('[data-locked]');
  if (lock) {
    const row = lock.closest('.mfm-record-row');
    row.classList.add('is-tip'); lock.classList.remove('is-shake'); void lock.offsetWidth; lock.classList.add('is-shake');
    say(byK('vid').why);
    setTimeout(() => { if (root.isConnected) row.classList.remove('is-tip'); }, 1600);
    return;
  }
  const u = e.target.closest('[data-undo]');
  if (u) undo(+u.dataset.undo);
});
root.addEventListener('submit', e => { e.preventDefault(); commit(true); });
root.addEventListener('keydown', e => {
  if (!editing || !e.target.closest('.mfm-record-edit')) return;
  if (e.key === 'Escape') { e.preventDefault(); cancel(); }
  else if (e.key === 'Enter' && e.target.matches('.mfm-record-in') && !e.isComposing) { e.preventDefault(); commit(true); }
});
/* picking from a native select is already a decision: save it */
root.addEventListener('change', e => { if (editing && e.target.matches('select.mfm-record-in')) commit(true); });
root.addEventListener('input', e => {
  if (!e.target.matches('.mfm-record-in[aria-invalid="true"]') || !editing) return;
  if (!validate(editing, e.target.value.trim())) { e.target.removeAttribute('aria-invalid'); rowOf(editing.k).querySelector('.mfm-record-err').textContent = ''; }
});
root.addEventListener('focusout', e => {
  const form = e.target.closest('.mfm-record-edit');
  if (!form || form.contains(e.relatedTarget)) return;
  const f = editing;
  setTimeout(() => {
    if (!root.isConnected || editing !== f || !f) return;
    if (!form.isConnected || form.contains(doc.activeElement)) return;
    commit(false);
  }, 0);
});

rows.innerHTML = F.map(rowHTML).join('');
syncSub();
renderLog();
const tick = setInterval(() => {
  if (!root.isConnected) { clearInterval(tick); return; }
  logEl.querySelectorAll('.mfm-record-entry').forEach((li, i) => { const t = li.querySelector('time'); if (t && log[i]) t.textContent = ago(log[i].at); });
}, 20000);

css:
.mfm-address {
  /* re-theme with these five */
  --mfm-address-bg: oklch(0.978 0.012 88);
  --mfm-address-ink: oklch(0.27 0.03 250);
  --mfm-address-accent: oklch(0.63 0.19 38);
  --mfm-address-ok: oklch(0.54 0.12 155);
  --mfm-address-bad: oklch(0.52 0.19 18);

  --mfm-address-mute: color-mix(in oklch, var(--mfm-address-ink) 55%, var(--mfm-address-bg));
  --mfm-address-line: color-mix(in oklch, var(--mfm-address-ink) 14%, transparent);
  --mfm-address-land: color-mix(in oklch, var(--mfm-address-bg), oklch(0.9 0.03 95) 40%);
  --mfm-address-water: oklch(0.85 0.05 228);
  --mfm-address-green: oklch(0.89 0.065 140);
  --mfm-address-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-address-fly: cubic-bezier(.65, 0, .2, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px; margin: 0;
  display: grid; gap: 14px; padding: 12px 12px 14px;
  border-radius: 18px; background: var(--mfm-address-bg); color: var(--mfm-address-ink);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-address-ink) 9%, transparent), 0 24px 48px -26px oklch(0 0 0 / .55);
  font: 400 14px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-address-accent); outline-offset: 2px; }

  /* ── map ── */
  & .mfm-address-map {
    position: relative; overflow: hidden; border-radius: 11px;
    height: clamp(122px, 40cqi, 158px);
    background: var(--mfm-address-land);
    box-shadow: inset 0 0 0 1px var(--mfm-address-line);
  }
  & .mfm-address-svg { display: block; width: 100%; height: 100%; }
  & .mfm-address-world, & .mfm-address-labels text, & .mfm-address-depot, & .mfm-address-pin {
    transform-box: view-box; transform-origin: 0 0;
    transition: transform .95s var(--mfm-address-fly);
  }
  & .mfm-address-land { fill: var(--mfm-address-land); }
  & .mfm-address-park { fill: var(--mfm-address-green); }
  & .mfm-address-water { fill: var(--mfm-address-water); }
  & .mfm-address-river { fill: none; stroke: var(--mfm-address-water); stroke-width: 6; stroke-linecap: round; }
  & .mfm-address-minor path { fill: none; stroke: white; stroke-width: 1.6; stroke-linecap: round; opacity: .9; }
  & .mfm-address-major path {
    fill: none; stroke: white; stroke-width: 3.6; stroke-linecap: round;
    filter: drop-shadow(0 0 .6px color-mix(in oklch, var(--mfm-address-ink) 40%, transparent));
  }
  & .mfm-address-zone {
    fill: color-mix(in oklch, var(--mfm-address-accent) 5%, transparent);
    stroke: color-mix(in oklch, var(--mfm-address-accent) 55%, transparent); stroke-width: 1.2; stroke-dasharray: 4 4;
    vector-effect: non-scaling-stroke; animation: mfm-address-march 3s linear infinite;
  }
  & .mfm-address-dot {
    fill: color-mix(in oklch, var(--mfm-address-ink) 30%, var(--mfm-address-land)); stroke: var(--mfm-address-land); stroke-width: .8;
    transform-box: fill-box; transform-origin: center; transition: fill .2s, scale .35s var(--mfm-address-spring);
    &.is-hit { fill: var(--mfm-address-accent); scale: 1.35; }
    &.is-active { fill: var(--mfm-address-accent); scale: 2; stroke: white; stroke-width: 1; }
  }
  & .mfm-address-route {
    fill: none; stroke: var(--mfm-address-accent); stroke-width: 2; stroke-linecap: round;
    vector-effect: non-scaling-stroke; stroke-dasharray: 1; stroke-dashoffset: 1;
    &.is-on { transition: stroke-dashoffset .8s cubic-bezier(.3, .7, .2, 1); stroke-dashoffset: 0; }
    &.is-out { stroke: var(--mfm-address-bad); stroke-dasharray: .02 .018; stroke-dashoffset: 0; opacity: .8; transition: opacity .3s; }
    &.is-hidden { opacity: 0; transition: none; }
  }
  & .mfm-address-labels text {
    font: 650 6.6px/1 system-ui, -apple-system, sans-serif; letter-spacing: .14em;
    fill: color-mix(in oklch, var(--mfm-address-ink) 52%, transparent); text-anchor: middle;
    paint-order: stroke; stroke: var(--mfm-address-land); stroke-width: 2.2px; stroke-linejoin: round;
    &.is-park { font-weight: 500; font-style: italic; letter-spacing: .02em; font-size: 6.4px; fill: oklch(0.45 0.08 145); stroke: var(--mfm-address-green); }
    &.is-water { font-weight: 500; font-style: italic; letter-spacing: .06em; fill: oklch(0.45 0.07 235); stroke: none; }
  }
  & .mfm-address-depot {
    & rect { fill: var(--mfm-address-ink); }
    & path { fill: none; stroke: var(--mfm-address-bg); stroke-width: 1.4; stroke-linejoin: round; stroke-linecap: round; }
    & text {
      font: 700 5.6px/1 system-ui, -apple-system, sans-serif; letter-spacing: .16em; text-anchor: middle; fill: var(--mfm-address-ink);
      paint-order: stroke; stroke: var(--mfm-address-land); stroke-width: 2px; stroke-linejoin: round;
    }
  }
  & .mfm-address-pulse {
    fill: none; stroke: var(--mfm-address-ink); stroke-width: 1.2; opacity: 0;
    transform-box: fill-box; transform-origin: center; animation: mfm-address-pulse 2.6s cubic-bezier(.2, .6, .3, 1) infinite;
  }
  & .mfm-address-pin {
    opacity: 0; transition: transform .95s var(--mfm-address-fly), opacity .2s;
    & .mfm-address-drop path { fill: var(--mfm-address-accent); stroke: color-mix(in oklch, var(--mfm-address-accent), black 25%); stroke-width: .8; }
    & .mfm-address-drop circle { fill: white; }
    & .mfm-address-shadow { fill: oklch(0 0 0 / .25); }
    & .mfm-address-ripple { fill: none; stroke: var(--mfm-address-accent); stroke-width: 1.5; opacity: 0; transform-box: fill-box; transform-origin: center; }
    &.is-on { opacity: 1; }
    &.is-unverified .mfm-address-drop path { fill: var(--mfm-address-bg); stroke: var(--mfm-address-mute); stroke-dasharray: 2 1.5; }
    &.is-unverified .mfm-address-drop circle { fill: var(--mfm-address-mute); }
    &.is-out .mfm-address-drop path { fill: var(--mfm-address-bad); stroke: color-mix(in oklch, var(--mfm-address-bad), black 25%); }
  }
  & .mfm-address-scale {
    position: absolute; right: 8px; bottom: 6px; display: grid; justify-items: end; gap: 2px;
    font: 600 9.5px/1 ui-monospace, Menlo, monospace; color: color-mix(in oklch, var(--mfm-address-ink) 65%, transparent);
    & i { width: var(--mfm-address-km, 25px); height: 4px; border: 1.2px solid currentColor; border-top: 0; transition: width .95s var(--mfm-address-fly); }
  }
  &.is-off .mfm-address-zone, &.is-off .mfm-address-pulse { animation-play-state: paused; }

  /* ── fields ── */
  & .mfm-address-fields {
    display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 10px 10px; padding: 0 4px;
    grid-template-areas: "street street" "unit unit" "town post";
  }
  & .mfm-address-street { grid-area: street; position: relative; z-index: 4; }
  & .mfm-address-unit { grid-area: unit; }
  & .mfm-address-town { grid-area: town; }
  & .mfm-address-post { grid-area: post; }
  & .mfm-address-f {
    display: grid; gap: 5px; min-width: 0;
    & label { font-size: 12px; font-weight: 600; & i { font-style: normal; font-weight: 450; color: var(--mfm-address-mute); } }
    & input {
      width: 100%; height: 40px; padding: 0 11px; border-radius: 10px; background: white;
      border: 1px solid color-mix(in oklch, var(--mfm-address-ink) 18%, transparent);
      font: 500 14px/1 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--mfm-address-ink);
      transition: border-color .2s, box-shadow .25s, background-color .3s;
      &::placeholder { color: color-mix(in oklch, var(--mfm-address-ink) 38%, transparent); font-weight: 400; }
      &:hover { border-color: color-mix(in oklch, var(--mfm-address-ink) 30%, transparent); }
      &:focus { outline: none; border-color: var(--mfm-address-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-address-accent) 17%, transparent); }
      &:user-invalid, &[aria-invalid="true"] { border-color: var(--mfm-address-bad); box-shadow: 0 0 0 4px color-mix(in oklch, var(--mfm-address-bad) 13%, transparent); }
      &.is-filled { animation: mfm-address-filled 1.8s ease-out; }
      &.is-typing { caret-color: transparent; }
    }
  }
  & .mfm-address-post input { font-family: ui-monospace, Menlo, monospace; font-size: 13.5px; text-transform: uppercase; letter-spacing: .04em; }
  & .mfm-address-anchor {
    position: relative;
    & input { padding-left: 34px; }
  }
  & .mfm-address-lead { position: absolute; left: 11px; top: 12px; width: 16px; height: 16px; fill: none; stroke: var(--mfm-address-mute); stroke-width: 1.6; stroke-linecap: round; pointer-events: none; }

  & .mfm-address-pop {
    position: absolute; left: 0; right: 0; top: calc(100% + 6px); margin: 0; padding: 5px; list-style: none;
    max-height: 214px; overflow-y: auto; overscroll-behavior: contain;
    border-radius: 13px; background: white; border: 1px solid var(--mfm-address-line);
    box-shadow: 0 22px 44px -14px color-mix(in oklch, var(--mfm-address-ink) 40%, transparent);
    opacity: 0; visibility: hidden; translate: 0 -4px; clip-path: inset(0 0 100% 0 round 13px);
    transition: opacity .15s, translate .2s, clip-path .2s ease-in, visibility 0s .2s;
    scrollbar-width: thin;
  }
  &.is-open .mfm-address-pop {
    opacity: 1; visibility: visible; translate: 0 0; clip-path: inset(0 0 0 0 round 13px);
    transition: opacity .2s, translate .4s cubic-bezier(.16, 1, .3, 1), clip-path .4s cubic-bezier(.16, 1, .3, 1), visibility 0s;
  }
  & .mfm-address-opt {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 9px;
    padding: 7px 9px; border-radius: 9px; cursor: pointer;
    & > svg { width: 16px; height: 16px; fill: none; stroke: var(--mfm-address-mute); stroke-width: 1.5; }
    & b { display: block; font-size: 13.5px; font-weight: 560; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { display: block; font-size: 11.5px; color: var(--mfm-address-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & mark { background: none; color: inherit; font-weight: 750; box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--mfm-address-accent) 45%, transparent); }
    & em {
      font: 600 11px/1 ui-monospace, Menlo, monospace; font-style: normal; font-variant-numeric: tabular-nums; color: var(--mfm-address-mute);
      &.is-out { font-family: system-ui, sans-serif; font-size: 10.5px; padding: 3px 6px; border-radius: 5px; color: var(--mfm-address-bad); background: color-mix(in oklch, var(--mfm-address-bad) 9%, transparent); }
    }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--mfm-address-accent) 10%, white); & > svg { stroke: var(--mfm-address-accent); } }
  }
  & .mfm-address-none { padding: 14px 12px; font-size: 12.5px; color: var(--mfm-address-mute); text-wrap: pretty; & b { color: var(--mfm-address-ink); } }

  /* ── status + submit ── */
  & .mfm-address-foot { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 0 4px; }
  & .mfm-address-status {
    display: flex; gap: 7px; align-items: flex-start; margin: 0; font-size: 12.5px; line-height: 1.35; color: var(--mfm-address-mute); text-wrap: pretty;
    & svg { width: 15px; height: 15px; margin-top: 1px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
    & b { font-variant-numeric: tabular-nums; font-weight: 650; }
    &.is-ok { color: color-mix(in oklch, var(--mfm-address-ok), black 12%); }
    &.is-out { color: var(--mfm-address-bad); }
    &.is-warn { color: oklch(0.52 0.12 70); }
    &.is-new { animation: mfm-address-status .4s cubic-bezier(.16, 1, .3, 1); }
  }
  & .mfm-address-go {
    display: inline-flex; align-items: center; gap: 7px; height: 40px; padding: 0 16px; border: 0; border-radius: 11px;
    background: var(--mfm-address-ink); color: var(--mfm-address-bg); font-weight: 640; font-size: 13.5px; white-space: nowrap;
    transition: background-color .2s, color .2s, transform .35s var(--mfm-address-spring);
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mfm-address-ink), var(--mfm-address-accent) 25%); }
    &:active:not(:disabled) { transform: scale(.95); }
    &:disabled { background: color-mix(in oklch, var(--mfm-address-ink) 8%, transparent); color: color-mix(in oklch, var(--mfm-address-ink) 38%, transparent); cursor: not-allowed; }
    &[aria-busy="true"] { pointer-events: none; & .mfm-address-spin { display: block; } }
    &.is-done { background: color-mix(in oklch, var(--mfm-address-ok) 14%, white); color: color-mix(in oklch, var(--mfm-address-ok), black 15%); }
  }
  & .mfm-address-spin {
    display: none; width: 13px; height: 13px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, var(--mfm-address-bg) 35%, transparent); border-top-color: var(--mfm-address-bg);
    animation: mfm-address-spin .7s linear infinite;
  }

  @container (max-width: 280px) {
    & .mfm-address-fields { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
    & .mfm-address-foot { grid-template-columns: 1fr; }
    & .mfm-address-go { justify-content: center; }
    & .mfm-address-opt em:not(.is-out) { display: none; }
  }
}

@keyframes mfm-address-march { to { stroke-dashoffset: -16; } }
@keyframes mfm-address-pulse { 0% { opacity: .5; scale: .6; } 80%, 100% { opacity: 0; scale: 2.1; } }
@keyframes mfm-address-filled { 0%, 30% { background-color: color-mix(in oklch, var(--mfm-address-accent) 13%, white); } }
@keyframes mfm-address-status { from { opacity: 0; translate: 0 4px; } }
@keyframes mfm-address-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-address {
    & .mfm-address-world, & .mfm-address-labels text, & .mfm-address-depot, & .mfm-address-pin, & .mfm-address-scale i { transition: none; }
    & .mfm-address-zone, & .mfm-address-pulse { animation: none; }
    & .mfm-address-route.is-on { transition: none; }
    & .mfm-address-dot { transition: fill .15s; }
    & .mfm-address-pop, &.is-open .mfm-address-pop { translate: none; clip-path: none; }
    & .mfm-address-f input.is-filled, & .mfm-address-status.is-new { animation: none; }
  }
}

