const $ = s => root.querySelector(s);
const svg = $('[data-svg]'), world = $('[data-world]'), route = $('[data-route]'), depotEl = $('[data-depot]'), pin = $('[data-pin]');
const dotsG = $('[data-dots]'), street = $('[data-street]'), list = $('[data-list]'), unit = $('[data-unit]');
const town = $('[data-town]'), post = $('[data-post]'), status = $('[data-status]'), go = $('[data-go]'), goLabel = $('[data-golabel]');
const labels = [...root.querySelectorAll('.mfm-address-labels text')];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const uid = 'mfm-address-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const SVGNS = 'http://www.w3.org/2000/svg';
const ICON = {
  info: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="M8 7.2v4M8 4.9v.1"/></svg>',
  ok: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="m5.4 8.2 1.8 1.8 3.5-3.8"/></svg>',
  out: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="m5.8 5.8 4.4 4.4M10.2 5.8l-4.4 4.4"/></svg>',
  warn: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.5 14 13H2Z"/><path d="M8 6.6v3M8 11.4v.1"/></svg>',
  pin: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 14.5s4.75-4.3 4.75-8a4.75 4.75 0 0 0-9.5 0c0 3.7 4.75 8 4.75 8Z"/><circle cx="8" cy="6.5" r="1.6"/></svg>'
};

/* the map is in metres: 1 unit = 40 m, the depot sits at (118, 98), the zone is 5 km */
const M_PER_UNIT = 40, ZONE_KM = 5, DEPOT = { x: 118, y: 98 }, VW = 360, VH = 150;
const A = [
  ['14 Wharf Lane', 'Port Ellery', 'PE1 4QD', 108, 112], ['220 Cooper Street', 'Port Ellery', 'PE2 7LN', 160, 58],
  ['230 Cooper Street', 'Port Ellery', 'PE2 7LP', 166, 50], ['7 Lantern Row', 'Port Ellery', 'PE1 2HW', 98, 78],
  ['88 Millrace Road', 'Port Ellery', 'PE3 9TA', 204, 118], ['31 Saltmarsh Avenue', 'Hollin Bay', 'HB4 1RE', 34, 104],
  ['5 Chandler’s Yard', 'Port Ellery', 'PE1 6XP', 138, 112], ['412 Kestrel Drive', 'Ashcombe', 'AC7 3MG', 318, 40],
  ['26 Kestrel Drive', 'Ashcombe', 'AC7 1MB', 276, 30], ['19 Orchard Mews', 'Port Ellery', 'PE2 5BS', 186, 84],
  ['63 Tannery Close', 'Port Ellery', 'PE3 1JU', 226, 60], ['2 Beacon Hill', 'Hollin Bay', 'HB2 8EF', 22, 52],
  ['140 Ropewalk', 'Port Ellery', 'PE1 3DA', 76, 92], ['9 Fernside Crescent', 'Ashcombe', 'AC2 6PL', 296, 120],
  ['77 Weir Street', 'Port Ellery', 'PE3 4KN', 190, 34], ['1 Gull Terrace', 'Hollin Bay', 'HB1 2WW', 48, 128]
].map((a, i) => {
  const km = Math.hypot(a[3] - DEPOT.x, a[4] - DEPOT.y) * M_PER_UNIT / 1000;
  return { i, street: a[0], town: a[1], post: a[2], x: a[3], y: a[4], km, inZone: km <= ZONE_KM };
});

let view = { s: 1, tx: 0, ty: 0 }, chosen = null, verified = false, isOpen = false, hits = [], active = -1, gen = 0, saved = false;

/* ── map ── */
A.forEach(a => {
  const c = document.createElementNS(SVGNS, 'circle');
  c.setAttribute('class', 'mfm-address-dot'); c.setAttribute('cx', a.x); c.setAttribute('cy', a.y); c.setAttribute('r', 2.1);
  dotsG.append(c); a.dot = c;
});
const at = (x, y) => 'translate(' + (x * view.s + view.tx).toFixed(2) + 'px,' + (y * view.s + view.ty).toFixed(2) + 'px)';
function place() {
  world.style.transform = 'translate(' + view.tx.toFixed(2) + 'px,' + view.ty.toFixed(2) + 'px) scale(' + view.s.toFixed(4) + ')';
  labels.forEach(t => { const p = t.dataset.at.split(','); t.style.transform = at(+p[0], +p[1]); });
  depotEl.style.transform = at(DEPOT.x, DEPOT.y);
  if (chosen) pin.style.transform = at(chosen.x, chosen.y);
  const w = svg.getBoundingClientRect().width || 340;
  root.style.setProperty('--mfm-address-km', (1000 / M_PER_UNIT * view.s * w / VW).toFixed(1) + 'px');
}
/* fit the depot and the pin with padding, never zooming past 2x or showing past the map edge */
function fit(a) {
  if (!a) { view = { s: 1, tx: 0, ty: 0 }; place(); return; }
  const pad = 30, x0 = Math.min(a.x, DEPOT.x) - pad, x1 = Math.max(a.x, DEPOT.x) + pad;
  const y0 = Math.min(a.y, DEPOT.y) - pad, y1 = Math.max(a.y, DEPOT.y) + pad;
  const s = Math.max(1, Math.min(2, VW / (x1 - x0), VH / (y1 - y0)));
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  const tx = Math.min(0, Math.max(VW - VW * s, VW / 2 - cx * s)), ty = Math.min(0, Math.max(VH - VH * s, VH / 2 - cy * s));
  view = { s, tx, ty };
  place();
}
function drawRoute(a) {
  const mx = (a.x + DEPOT.x) / 2, my = (a.y + DEPOT.y) / 2, dx = a.x - DEPOT.x, dy = a.y - DEPOT.y;
  const k = 0.22, cx = mx - dy * k, cy = my + dx * k;
  route.setAttribute('d', 'M' + DEPOT.x + ' ' + DEPOT.y + 'Q' + cx.toFixed(1) + ' ' + cy.toFixed(1) + ' ' + a.x + ' ' + a.y);
  route.setAttribute('class', 'mfm-address-route is-hidden');
  void route.getBoundingClientRect();
  route.setAttribute('class', 'mfm-address-route ' + (a.inZone ? 'is-on' : 'is-out'));
}
function dropPin(a) {
  pin.style.transition = 'none';
  pin.style.transform = at(a.x, a.y);
  void pin.getBoundingClientRect();
  pin.style.transition = '';
  pin.setAttribute('class', 'mfm-address-pin is-on' + (a.inZone ? '' : ' is-out'));
  if (RM.matches) return;
  pin.querySelector('.mfm-address-drop').animate([{ transform: 'translateY(-34px)', opacity: 0 }, { transform: 'translateY(-34px)', opacity: 1, offset: .12 }, { transform: 'none', opacity: 1 }],
    { duration: 720, easing: 'linear(0, 0.06 6%, 0.24 14%, 0.53 22%, 0.92 30%, 0.98 33%, 0.88 39%, 0.85 42%, 0.88 46%, 1 55%, 0.97 61%, 0.96 64%, 0.97 67%, 1 74%, 0.995 82%, 1)' });
  pin.querySelector('.mfm-address-shadow').animate([{ transform: 'scale(.2)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 520, easing: 'cubic-bezier(.3,.7,.2,1)' });
  pin.querySelector('.mfm-address-ripple').animate([{ transform: 'scale(.1)', opacity: .9 }, { transform: 'scale(1.6)', opacity: 0 }], { duration: 900, delay: 300, easing: 'cubic-bezier(.2,.6,.3,1)' });
}

/* ── suggestions ── */
const norm = s => s.toLowerCase().replace(/[’']/g, '').replace(/\s+/g, ' ');
function search(q) {
  const toks = norm(q).trim().split(' ').filter(Boolean);
  if (!toks.length) return [];
  return A.map(a => {
    const hay = norm(a.street + ' ' + a.town + ' ' + a.post);
    if (!toks.every(t => hay.includes(t))) return null;
    const st = norm(a.street);
    return { a, score: (st.startsWith(toks[0]) ? 100 : 0) + (st.includes(' ' + toks[0]) ? 30 : 0) - a.km };
  }).filter(Boolean).sort((p, q2) => q2.score - p.score).slice(0, 6).map(r => r.a);
}
function mark(text, q) {
  const toks = norm(q).trim().split(' ').filter(Boolean), t = norm(text), on = new Array(text.length).fill(false);
  toks.forEach(k => { const i = t.indexOf(k); if (i >= 0) for (let j = i; j < i + k.length; j++) on[j] = true; });
  let out = '', open = false;
  Array.from(text).forEach((c, i) => {
    if (on[i] && !open) { out += '<mark>'; open = true; } else if (!on[i] && open) { out += '</mark>'; open = false; }
    out += esc(c);
  });
  return out + (open ? '</mark>' : '');
}
const km = v => v.toFixed(1) + ' km';
function renderList() {
  const q = street.value;
  hits = search(q);
  A.forEach(a => a.dot.classList.toggle('is-hit', hits.includes(a)));
  if (!q.trim()) { close(); return; }
  list.innerHTML = hits.length ? hits.map((a, i) => '<li role="option" class="mfm-address-opt" id="' + uid + '-o' + a.i + '" data-i="' + a.i + '" aria-selected="false">' + ICON.pin +
    '<span><b>' + mark(a.street, q) + '</b><small>' + esc(a.town) + ' · ' + esc(a.post) + '</small></span>' +
    (a.inZone ? '<em>' + km(a.km) + '</em>' : '<em class="is-out">Out of zone</em>') + '</li>').join('')
    : '<li class="mfm-address-none" role="presentation">No match for <b>“' + esc(q.trim()) + '”</b>. Check the spelling, or fill in town and postcode yourself.</li>';
  open();
  setActive(hits.length ? 0 : -1);
}
function setActive(i) {
  active = i;
  [...list.querySelectorAll('[role="option"]')].forEach((o, k) => {
    o.setAttribute('aria-selected', String(k === i));
    if (k === i) {
      street.setAttribute('aria-activedescendant', o.id);
      if (o.offsetTop < list.scrollTop) list.scrollTop = o.offsetTop - 5;
      else if (o.offsetTop + o.offsetHeight > list.scrollTop + list.clientHeight) list.scrollTop = o.offsetTop + o.offsetHeight - list.clientHeight + 5;
    }
  });
  if (i < 0) street.removeAttribute('aria-activedescendant');
  A.forEach(a => a.dot.classList.toggle('is-active', i >= 0 && hits[i] === a));
}
function open() { if (isOpen) return; isOpen = true; root.classList.add('is-open'); street.setAttribute('aria-expanded', 'true'); }
function close() {
  if (!isOpen) return;
  isOpen = false; root.classList.remove('is-open'); street.setAttribute('aria-expanded', 'false'); street.removeAttribute('aria-activedescendant');
  A.forEach(a => a.dot.classList.remove('is-active'));
}

/* type a value in, character by character, like autofill done by a person */
function typeIn(inp, text, delay, token) {
  return new Promise(res => {
    inp.classList.remove('is-filled');
    if (RM.matches) { inp.value = text; res(); return; }
    inp.value = ''; inp.classList.add('is-typing');
    const t0 = performance.now() + delay;
    const step = now => {
      if (!root.isConnected) return;
      if (token !== gen) { inp.classList.remove('is-typing'); res(); return; }
      if (now < t0) { requestAnimationFrame(step); return; }
      const n = Math.min(text.length, Math.floor((now - t0) / 24) + 1);
      inp.value = text.slice(0, n);
      if (n < text.length) requestAnimationFrame(step);
      else { inp.classList.remove('is-typing'); void inp.offsetWidth; inp.classList.add('is-filled'); res(); }
    };
    requestAnimationFrame(step);
  });
}

function setStatus(kind, html) {
  status.className = 'mfm-address-status is-' + kind;
  status.innerHTML = ICON[kind === 'idle' ? 'info' : kind === 'ok' ? 'ok' : kind === 'out' ? 'out' : 'warn'] + '<span>' + html + '</span>';
  void status.offsetWidth; status.classList.add('is-new');
}
function sync() {
  const postOk = post.checkValidity() && post.value.trim(), townOk = town.value.trim();
  if (saved) return;
  if (!chosen && !street.value.trim()) setStatus('idle', 'We deliver within ' + ZONE_KM + ' km of our Harbour depot.');
  else if (!verified) setStatus('warn', 'Not verified — pick a suggestion so we can check the delivery zone.');
  else if (!chosen.inZone) setStatus('out', 'Outside our zone — <b>' + km(chosen.km) + '</b> from the depot, the limit is ' + ZONE_KM + ' km.');
  else setStatus('ok', 'In zone · <b>' + km(chosen.km) + '</b> from the depot · next-day delivery');
  go.disabled = !(verified && chosen && chosen.inZone && postOk && townOk);
  pin.classList.toggle('is-unverified', !!chosen && !verified);
}

async function choose(a) {
  const token = ++gen;
  chosen = a; verified = true; saved = false;
  go.classList.remove('is-done'); goLabel.textContent = 'Deliver here';
  street.value = a.street; close();
  A.forEach(d => d.dot.classList.remove('is-hit'));
  post.removeAttribute('aria-invalid');
  fit(a);
  route.setAttribute('class', 'mfm-address-route is-hidden');
  const flyMs = RM.matches ? 0 : 520;
  setTimeout(() => { if (root.isConnected && token === gen) { dropPin(a); setTimeout(() => { if (root.isConnected && token === gen) drawRoute(a); }, RM.matches ? 0 : 380); } }, flyMs);
  if (!unit.value) unit.focus({ preventScroll: true });
  await Promise.all([typeIn(town, a.town, 140, token), typeIn(post, a.post, 300, token)]);
  if (token === gen) sync();
}

street.id = uid + '-street'; list.id = uid + '-list'; street.setAttribute('aria-controls', list.id);
root.querySelectorAll('[data-l]').forEach(l => { const inp = root.querySelector('[data-' + l.dataset.l + ']'); if (!inp.id) inp.id = uid + '-' + l.dataset.l; l.htmlFor = inp.id; });

street.addEventListener('input', () => {
  if (chosen && street.value !== chosen.street) { verified = false; saved = false; gen++; }
  renderList(); sync();
});
street.addEventListener('keydown', e => {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    if (!isOpen) { renderList(); return; }
    if (hits.length) setActive((active + (e.key === 'ArrowDown' ? 1 : -1) + hits.length) % hits.length);
  } else if (e.key === 'Enter') {
    if (isOpen && hits[active]) { e.preventDefault(); choose(hits[active]); }
    else if (isOpen) { e.preventDefault(); }
  } else if (e.key === 'Escape') { if (isOpen) { e.preventDefault(); close(); A.forEach(a => a.dot.classList.remove('is-hit')); } }
  else if (e.key === 'Tab') close();
});
street.addEventListener('focus', () => { if (street.value.trim() && !verified) renderList(); });
street.addEventListener('blur', () => { close(); A.forEach(a => a.dot.classList.remove('is-hit')); });
list.addEventListener('pointerdown', e => e.preventDefault());
list.addEventListener('pointermove', e => { const o = e.target.closest('[role="option"]'); if (o) { const k = hits.indexOf(A[+o.dataset.i]); if (k !== active) setActive(k); } });
list.addEventListener('click', e => { const o = e.target.closest('[role="option"]'); if (o) choose(A[+o.dataset.i]); });

[town, post].forEach(inp => inp.addEventListener('input', () => {
  if (inp === post) post.value = post.value.toUpperCase();
  if (chosen && (town.value !== chosen.town || post.value.replace(/\s/g, '') !== chosen.post.replace(/\s/g, ''))) { verified = false; saved = false; }
  else if (chosen && street.value === chosen.street) verified = true;
  if (post.getAttribute('aria-invalid') && post.checkValidity()) post.removeAttribute('aria-invalid');
  sync();
}));
post.addEventListener('blur', () => { if (post.value && !post.checkValidity()) post.setAttribute('aria-invalid', 'true'); });

root.addEventListener('submit', e => {
  e.preventDefault();
  if (go.disabled || go.getAttribute('aria-busy') === 'true') return;
  go.setAttribute('aria-busy', 'true'); goLabel.textContent = 'Saving';
  setTimeout(() => {
    if (!root.isConnected) return;
    go.removeAttribute('aria-busy'); saved = true;
    goLabel.textContent = 'Saved'; go.classList.add('is-done'); go.disabled = true;
    setStatus('ok', 'Saved · deliveries to <b>' + esc(street.value) + (unit.value.trim() ? ', ' + esc(unit.value.trim()) : '') + '</b> arrive next day.');
  }, 800);
});
unit.addEventListener('input', () => { if (saved) { saved = false; go.classList.remove('is-done'); goLabel.textContent = 'Deliver here'; sync(); } });

/* pause the ambient map animation while it is off screen */
const io = new IntersectionObserver(es => { es.forEach(en => root.classList.toggle('is-off', !en.isIntersecting)); });
io.observe(root);
let roFrame = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
  cancelAnimationFrame(roFrame);
  roFrame = requestAnimationFrame(() => { if (!root.isConnected) return; place(); });
});
ro.observe(svg);

place();
sync();

css:
.mfm-sentence {
  /* re-theme with these four */
  --mfm-sentence-bg: oklch(0.966 0.019 80);
  --mfm-sentence-ink: oklch(0.24 0.03 40);
  --mfm-sentence-accent: oklch(0.47 0.16 345);
  --mfm-sentence-bad: oklch(0.53 0.19 27);

  --mfm-sentence-mute: color-mix(in oklch, var(--mfm-sentence-ink) 56%, var(--mfm-sentence-bg));
  --mfm-sentence-line: color-mix(in oklch, var(--mfm-sentence-ink) 13%, transparent);
  --mfm-sentence-paper: color-mix(in oklch, var(--mfm-sentence-bg), white 55%);
  --mfm-sentence-tint: color-mix(in oklch, var(--mfm-sentence-accent) 12%, var(--mfm-sentence-bg));
  --mfm-sentence-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-sentence-out: cubic-bezier(.16, 1, .3, 1);
  --mfm-sentence-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px; margin: 0;
  display: grid; gap: 13px; padding: 17px 18px 15px;
  border-radius: 18px; color: var(--mfm-sentence-ink);
  background:
    radial-gradient(100% 50% at 100% 0%, color-mix(in oklch, var(--mfm-sentence-accent) 7%, transparent), transparent 70%),
    var(--mfm-sentence-bg);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-sentence-ink) 9%, transparent), 0 24px 48px -26px oklch(0 0 0 / .6);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-sentence-accent); outline-offset: 3px; border-radius: 4px; }

  & .mfm-sentence-top { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  & .mfm-sentence-brand { font-size: 10.5px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; }
  & .mfm-sentence-city { font-size: 11.5px; color: var(--mfm-sentence-mute); font-variant-numeric: tabular-nums; }

  /* ── the sentence ── */
  & .mfm-sentence-say {
    margin: 0; font-family: var(--mfm-sentence-serif); font-size: clamp(1.05rem, .7rem + 3cqi, 1.36rem);
    line-height: 1.72; letter-spacing: -0.005em; text-wrap: pretty;
  }
  & .mfm-sentence-pick, & .mfm-sentence-money { position: relative; display: inline-flex; align-items: baseline; white-space: nowrap; }
  & .mfm-sentence-pick select, & .mfm-sentence-money input {
    appearance: none; margin: 0; padding: 0 0 1px; border: 0; border-radius: 0; background: transparent;
    font: inherit; font-style: italic; font-weight: 600; color: var(--mfm-sentence-accent); line-height: 1.25;
    border-bottom: 2px dashed color-mix(in oklch, var(--mfm-sentence-accent) 45%, transparent);
    cursor: pointer; transition: border-color .2s, background-color .2s;
    &:hover { border-bottom-style: solid; border-color: var(--mfm-sentence-accent); background: color-mix(in oklch, var(--mfm-sentence-accent) 6%, transparent); }
    &:focus-visible { outline: none; border-bottom-style: solid; border-color: var(--mfm-sentence-accent); background: var(--mfm-sentence-tint); border-radius: 3px 3px 0 0; }
    &.is-pulse { animation: mfm-sentence-pulse .6s var(--mfm-sentence-out); }
  }
  & .mfm-sentence-pick select { padding-right: 15px; text-overflow: clip; }
  & .mfm-sentence-pick svg { position: absolute; right: 1px; top: 50%; translate: 0 -40%; width: 11px; height: 11px; stroke-width: 2; color: var(--mfm-sentence-accent); pointer-events: none; }
  & .mfm-sentence-money {
    color: var(--mfm-sentence-accent); font-style: italic; font-weight: 600;
    & input { cursor: text; font-variant-numeric: tabular-nums; min-width: 2ch; caret-color: var(--mfm-sentence-accent); }
    & input[aria-invalid="true"] { color: var(--mfm-sentence-bad); border-bottom-color: var(--mfm-sentence-bad); border-bottom-style: solid; }
  }
  & .mfm-sentence-err {
    margin: -8px 0 0; font-size: 12px; font-weight: 500; color: var(--mfm-sentence-bad);
    &:empty { display: none; }
  }
  & .mfm-sentence-measure { position: absolute; visibility: hidden; white-space: pre; font-family: var(--mfm-sentence-serif); font-style: italic; font-weight: 600; pointer-events: none; left: 0; top: 0; }

  /* ── results ── */
  & .mfm-sentence-out {
    display: grid; gap: 10px; padding: 14px 14px 10px; border-radius: 14px; background: var(--mfm-sentence-paper);
    box-shadow: inset 0 0 0 1px var(--mfm-sentence-line);
    transition: opacity .25s, filter .25s;
  }
  &.is-invalid .mfm-sentence-out { opacity: .45; filter: grayscale(.6); }
  & .mfm-sentence-count { display: flex; align-items: center; gap: 10px; }
  & .mfm-sentence-odo {
    display: inline-flex; height: 1.1em; overflow: hidden; font: 700 30px/1.1 var(--mfm-sentence-serif); font-variant-numeric: tabular-nums; letter-spacing: -0.02em;
    & span { display: block; width: .62em; text-align: center; transition: translate .7s var(--mfm-sentence-spring); translate: 0 calc(var(--d) * -1.1em); }
    & span.is-in { animation: mfm-sentence-digit .45s var(--mfm-sentence-out); }
    & i { display: block; font-style: normal; height: 1.1em; }
  }
  & .mfm-sentence-label {
    display: grid; line-height: 1.25;
    & b { font-size: 13.5px; font-weight: 640; }
    & small { font-size: 12px; color: var(--mfm-sentence-mute); font-variant-numeric: tabular-nums; }
  }

  & .mfm-sentence-strip { position: relative; height: 66px; margin: 0; }
  & .mfm-sentence-dots { position: absolute; left: 0; right: 0; top: 18px; height: 30px; }
  & .mfm-sentence-dot {
    position: absolute; left: var(--x); bottom: calc(var(--r) * 10px); width: 9px; height: 9px; margin-left: -4.5px; border-radius: 50%;
    border: 1.5px solid color-mix(in oklch, var(--mfm-sentence-ink) 35%, transparent); background: var(--mfm-sentence-paper);
    transition: left .6s var(--mfm-sentence-out), bottom .6s var(--mfm-sentence-out), background-color .25s, border-color .25s, scale .4s var(--mfm-sentence-spring);
    @starting-style { scale: 0; }
    &.is-in { background: var(--mfm-sentence-accent); border-color: var(--mfm-sentence-accent); }
    &.is-top { scale: 1.35; box-shadow: 0 0 0 2px var(--mfm-sentence-paper); z-index: 1; }
  }
  & .mfm-sentence-line {
    position: absolute; top: 0; bottom: 16px; left: var(--x, 50%); width: 0; border-left: 1.5px solid var(--mfm-sentence-ink);
    transition: left .55s var(--mfm-sentence-spring);
    & span {
      position: absolute; top: 0; left: 5px; padding: 1px 5px; border-radius: 4px;
      font: 650 10.5px/1.3 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap;
      background: var(--mfm-sentence-ink); color: var(--mfm-sentence-bg);
    }
    &.is-flip span { left: auto; right: 5px; }
  }
  & .mfm-sentence-axis {
    position: absolute; left: 0; right: 0; bottom: 0; display: flex; justify-content: space-between; padding-top: 3px;
    border-top: 1px solid var(--mfm-sentence-line); font: 500 10.5px/1.2 ui-monospace, Menlo, monospace; color: var(--mfm-sentence-mute); font-variant-numeric: tabular-nums;
  }

  & .mfm-sentence-list { list-style: none; margin: 0; padding: 0; display: grid; }
  & .mfm-sentence-row {
    display: grid; grid-template-columns: 6px minmax(0, 1fr) auto; align-items: center; gap: 11px; padding: 8px 0;
    border-top: 1px solid var(--mfm-sentence-line);
    transition: opacity .3s, translate .45s var(--mfm-sentence-out);
    @starting-style { opacity: 0; translate: 0 8px; }
    &::before { content: ""; align-self: stretch; border-radius: 3px; background: oklch(0.68 0.12 var(--h)); }
    & b { display: block; font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { display: block; font-size: 11.5px; color: var(--mfm-sentence-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
    & strong { font: 650 14px/1 var(--mfm-sentence-serif); font-variant-numeric: tabular-nums; }
    & strong em { font: 400 11px/1 system-ui, sans-serif; font-style: normal; color: var(--mfm-sentence-mute); }
  }
  & .mfm-sentence-more { padding: 7px 0 2px; border-top: 1px solid var(--mfm-sentence-line); font-size: 12px; color: var(--mfm-sentence-mute); }

  & .mfm-sentence-empty {
    display: none; gap: 8px; justify-items: start; padding: 6px 0 4px; font-size: 13px; text-wrap: pretty;
    & p { margin: 0; }
    & b { font-weight: 640; }
    & button {
      height: 32px; padding: 0 12px; border-radius: 9px; border: 1px solid color-mix(in oklch, var(--mfm-sentence-accent) 40%, transparent);
      background: var(--mfm-sentence-tint); color: var(--mfm-sentence-accent); font-weight: 650; font-size: 12.5px;
      transition: background-color .15s, transform .3s var(--mfm-sentence-spring);
      &:hover { background: color-mix(in oklch, var(--mfm-sentence-accent) 18%, var(--mfm-sentence-bg)); }
      &:active { transform: scale(.96); }
    }
  }
  &.is-empty {
    & .mfm-sentence-empty { display: grid; animation: mfm-sentence-rise .4s var(--mfm-sentence-out); }
    & .mfm-sentence-list { display: none; }
  }

  & .mfm-sentence-foot { display: flex; justify-content: flex-end; }
  & .mfm-sentence-go {
    display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 16px 0 14px; border: 0; border-radius: 11px;
    background: var(--mfm-sentence-ink); color: var(--mfm-sentence-bg); font-weight: 640; font-size: 13.5px;
    transition: background-color .2s, color .2s, transform .35s var(--mfm-sentence-spring);
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mfm-sentence-ink), var(--mfm-sentence-accent) 35%); }
    &:active:not(:disabled) { transform: scale(.95); }
    &:hover:not(:disabled) svg { animation: mfm-sentence-ring .6s ease-in-out; }
    &:disabled { background: color-mix(in oklch, var(--mfm-sentence-ink) 9%, transparent); color: color-mix(in oklch, var(--mfm-sentence-ink) 38%, transparent); cursor: not-allowed; }
    &[aria-busy="true"] { pointer-events: none; & svg { display: none; } & .mfm-sentence-spin { display: block; } }
    &.is-done { background: var(--mfm-sentence-tint); color: var(--mfm-sentence-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-sentence-accent) 30%, transparent); }
  }
  & .mfm-sentence-spin {
    display: none; width: 14px; height: 14px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, var(--mfm-sentence-bg) 35%, transparent); border-top-color: var(--mfm-sentence-bg);
    animation: mfm-sentence-spin .7s linear infinite;
  }
  & .mfm-sentence-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  @container (max-width: 290px) {
    & { padding: 15px 15px 14px; gap: 12px; }
    & .mfm-sentence-say { line-height: 1.66; }
    & .mfm-sentence-out { padding: 12px 12px 8px; }
    & .mfm-sentence-row:nth-child(n + 2) { display: none; }
    & .mfm-sentence-label small { display: none; }
    & .mfm-sentence-strip { height: 60px; }
    & .mfm-sentence-go { flex: 1; justify-content: center; }
  }
}

@keyframes mfm-sentence-pulse { 0% { background-color: color-mix(in oklch, var(--mfm-sentence-accent) 22%, transparent); } }
@keyframes mfm-sentence-digit { from { opacity: 0; filter: blur(3px); } }
@keyframes mfm-sentence-rise { from { opacity: 0; translate: 0 6px; } }
@keyframes mfm-sentence-ring { 0%, 100% { rotate: 0deg; } 25% { rotate: 14deg; } 50% { rotate: -10deg; } 75% { rotate: 6deg; } }
@keyframes mfm-sentence-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-sentence {
    & .mfm-sentence-odo span { transition: none; }
    & .mfm-sentence-odo span.is-in, & .mfm-sentence-pick select.is-pulse, & .mfm-sentence-money input.is-pulse { animation: none; }
    & .mfm-sentence-dot { transition: background-color .2s, border-color .2s; @starting-style { scale: 1; } }
    & .mfm-sentence-line { transition: none; }
    & .mfm-sentence-row { transition: none; @starting-style { opacity: 1; translate: 0 0; } }
    &.is-empty .mfm-sentence-empty { animation: none; }
    & .mfm-sentence-go:hover:not(:disabled) svg { animation: none; }
  }
}

