const $ = s => root.querySelector(s);
const sel = k => root.querySelector('[data-k="' + k + '"]');
const budgetIn = sel('budget'), odo = $('[data-odo]'), noun = $('[data-noun]'), median = $('[data-median]');
const strip = $('[data-strip]'), dotsEl = $('[data-dots]'), line = $('[data-line]'), lineLabel = $('[data-linelabel]');
const lo = $('[data-lo]'), hi = $('[data-hi]'), list = $('[data-list]'), empty = $('[data-empty]'), err = $('[data-err]');
const go = $('[data-go]'), goLabel = $('[data-golabel]'), live = $('[data-live]'), measure = $('[data-measure]'), total = $('[data-total]');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const usd = n => '$' + Math.round(n).toLocaleString('en-US');

/* ── a deterministic listings set (seeded), so every count below can be checked by hand ── */
let seed = 20261002;
const rnd = () => { seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const pick = a => a[Math.floor(rnd() * a.length)];
const AREAS = {
  'Northgate': { base: 1250, bed: 520, h: 32, streets: ['Quill Street', 'Larch Road', 'Tanner’s Walk', 'Hollis Avenue'] },
  'Riverside': { base: 1450, bed: 600, h: 222, streets: ['Ferry Lane', 'Wharf Row', 'Kingfisher Court', 'Mill Quay'] },
  'Old Market': { base: 1150, bed: 440, h: 80, streets: ['Cornhill', 'Draper Street', 'Bell Yard', 'Saddler Lane'] },
  'Halden Park': { base: 1600, bed: 640, h: 150, streets: ['Cedar Crescent', 'Park Terrace', 'Linden Grove', 'Orchard Rise'] }
};
const START = Date.UTC(2026, 8, 24), DAY = 864e5;
const L = Array.from({ length: 160 }, (_, id) => {
  const area = pick(Object.keys(AREAS)), A = AREAS[area], r = rnd();
  const beds = r < .14 ? 0 : r < .48 ? 1 : r < .8 ? 2 : 3;
  const rent = Math.round((A.base + beds * A.bed + (rnd() - .42) * 460) / 25) * 25;
  const flat = rnd() < .55 ? 'Flat ' + (1 + Math.floor(rnd() * 9)) + ', ' : '';
  return {
    id, area, beds, rent, h: A.h,
    addr: flat + (2 + Math.floor(rnd() * 180)) + ' ' + pick(A.streets),
    sqm: 26 + beds * 21 + Math.floor(rnd() * 15),
    pets: pick(['none', 'none', 'cat', 'dog', 'both']),
    avail: START + Math.floor(rnd() * 84) * DAY
  };
});
total.textContent = L.length;
const day = t => new Date(t).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

/* ── state ── */
const read = () => ({
  beds: +sel('beds').value, area: sel('area').value, pets: sel('pets').value,
  from: Date.parse(sel('from').value + 'T00:00:00Z'), budget: parseBudget(budgetIn.value)
});
function parseBudget(v) { const d = String(v).replace(/[^\d]/g, ''); return d ? +d : NaN; }
const fits = (l, q) => l.beds === q.beds && (q.area === 'any' || l.area === q.area) && l.avail <= q.from &&
  (q.pets === 'none' || l.pets === q.pets || l.pets === 'both');
const nounOf = q => q.beds === 0 ? 'studio' : q.beds + '-bedroom home';

/* ── content-sized controls (field-sizing is not everywhere yet, so measure) ── */
function size(el) {
  const text = el.tagName === 'SELECT' ? el.options[el.selectedIndex].text : (el.value || '0');
  measure.style.fontSize = getComputedStyle(el).fontSize;
  measure.style.fontVariantNumeric = el.tagName === 'INPUT' ? 'tabular-nums' : 'normal';
  measure.textContent = text;
  el.style.width = Math.ceil(measure.getBoundingClientRect().width + (el.tagName === 'SELECT' ? 17 : 1)) + 'px';
}
const sizeAll = () => root.querySelectorAll('select, input').forEach(size);

/* ── odometer ── */
function setCount(n) {
  const s = String(n);
  if (odo.children.length !== s.length) {
    odo.innerHTML = Array.from(s, () => '<span class="is-in" style="--d:0">' + Array.from({ length: 10 }, (_, k) => '<i>' + k + '</i>').join('') + '</span>').join('');
    void odo.offsetWidth;
  }
  [...odo.children].forEach((c, i) => c.style.setProperty('--d', s[i]));
  odo.setAttribute('aria-label', s);
}

/* ── dot strip: every candidate that fits everything except the budget ── */
let prevBudget = null;
function renderStrip(cands, q) {
  const w = strip.clientWidth || 300;
  const vals = cands.map(l => l.rent).concat(isNaN(q.budget) ? [] : [q.budget]);
  const a = Math.floor((Math.min(...vals) - 100) / 250) * 250, b = Math.ceil((Math.max(...vals) + 100) / 250) * 250;
  const X = v => (v - a) / (b - a);
  lo.textContent = usd(a); hi.textContent = usd(b);
  const sorted = cands.slice().sort((p, r) => p.rent - r.rent), rows = [];
  const keep = new Map([...dotsEl.children].map(d => [+d.dataset.id, d]));
  const top = new Set(sorted.filter(l => l.rent <= q.budget).slice(0, 2).map(l => l.id));
  const changed = [];
  sorted.forEach(l => {
    const px = X(l.rent) * w;
    let r = 0; while (rows[r] != null && px - rows[r] < 10 && r < 2) r++;
    rows[r] = px;
    let d = keep.get(l.id);
    if (!d) { d = document.createElement('i'); d.className = 'mfm-sentence-dot'; d.dataset.id = l.id; dotsEl.append(d); }
    keep.delete(l.id);
    d.style.setProperty('--x', (X(l.rent) * 100).toFixed(2) + '%');
    d.style.setProperty('--r', r);
    const inB = l.rent <= q.budget;
    if (d.classList.contains('is-in') !== inB) changed.push([d, Math.abs(l.rent - (prevBudget == null ? q.budget : prevBudget))]);
    d.classList.toggle('is-in', inB);
    d.classList.toggle('is-top', top.has(l.id));
    d.title = l.addr + ' · ' + usd(l.rent);
  });
  keep.forEach(d => d.remove());
  /* the fill sweeps outward from where the line used to be */
  changed.sort((p, r) => p[1] - r[1]).forEach(([d], k) => { d.style.transitionDelay = RM.matches ? '0ms' : Math.min(k * 26, 400) + 'ms'; });
  if (!isNaN(q.budget)) {
    const x = Math.max(0, Math.min(1, X(q.budget)));
    line.style.setProperty('--x', (x * 100).toFixed(2) + '%');
    line.classList.toggle('is-flip', x > .72);
    lineLabel.textContent = usd(q.budget);
    prevBudget = q.budget;
  }
}

/* ── top matches, keyed + FLIP ── */
const tail = document.createElement('li'); tail.className = 'mfm-sentence-more';
function renderList(matches) {
  const top = matches.slice().sort((p, r) => p.rent - r.rent || p.id - r.id).slice(0, 2);
  const first = new Map([...list.children].filter(n => n !== tail).map(n => [n.dataset.id, n.getBoundingClientRect().top]));
  const old = new Map([...list.children].filter(n => n !== tail).map(n => [n.dataset.id, n]));
  const nodes = top.map(l => {
    let n = old.get(String(l.id));
    if (!n) {
      n = document.createElement('li'); n.className = 'mfm-sentence-row'; n.dataset.id = l.id; n.style.setProperty('--h', l.h);
      n.innerHTML = '<span><b>' + esc(l.addr) + '</b><small>' + (l.beds ? l.beds + ' bd' : 'Studio') + ' · ' + l.sqm + ' m² · ' + esc(l.area) +
        ' · from ' + day(l.avail) + '</small></span><strong>' + usd(l.rent) + ' <em>/mo</em></strong>';
    }
    return n;
  });
  const more = matches.length - top.length;
  tail.textContent = more > 0 ? '+ ' + more + ' more ' + (more === 1 ? 'match' : 'matches') + ', cheapest first' : 'That’s every match';
  /* reconcile in place: re-inserting an unchanged row would replay its @starting-style entry */
  const want = [...nodes, tail];
  [...list.children].forEach(n => { if (!want.includes(n)) n.remove(); });
  want.forEach((n, i) => {
    const ref = list.children[i] || null;
    if (ref === n) return;
    if (n.isConnected && typeof list.moveBefore === 'function') { try { list.moveBefore(n, ref); return; } catch (e) { /* fall through */ } }
    list.insertBefore(n, ref);
  });
  if (RM.matches) return;
  nodes.forEach(n => {
    const t = first.get(n.dataset.id); if (t == null) return;
    const dy = t - n.getBoundingClientRect().top;
    if (Math.abs(dy) > .5) n.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: 'cubic-bezier(.16,1,.3,1)' });
  });
}

/* ── empty state: always offer a way out that is known to work ── */
const label = (k, v) => [...sel(k).options].find(o => o.value === String(v)).text;
function rescue(q, cands) {
  if (cands.length) {
    const m = Math.min(...cands.map(l => l.rent));
    return { html: 'Nothing under <b>' + usd(q.budget) + '</b> yet — the lowest match is <b>' + usd(m) + '</b>.', btn: 'Raise budget to ' + usd(m), act: () => { budgetIn.value = m.toLocaleString('en-US'); } };
  }
  const tries = [
    ['area', 'any', 'Try any neighbourhood'], ['from', '2027-01-01', 'Try from 1 January'],
    ['pets', 'none', 'Search without pets'], ['beds', String(Math.max(0, q.beds - 1)), 'Try one bedroom fewer']
  ];
  for (const [k, v, txt] of tries) {
    if (sel(k).value === v) continue;
    const q2 = Object.assign({}, q, { [k]: k === 'from' ? Date.parse(v + 'T00:00:00Z') : k === 'beds' ? +v : v });
    const n = L.filter(l => fits(l, q2) && l.rent <= q.budget).length || L.filter(l => fits(l, q2)).length;
    if (n) return { html: 'No ' + esc(nounOf(q)) + 's ' + (q.area === 'any' ? '' : 'in <b>' + esc(q.area) + '</b> ') + 'for ' + esc(label('pets', q.pets)) + ' by ' + esc(label('from', sel('from').value)) + '.', btn: txt, act: () => { sel(k).value = v; } };
  }
  return { html: 'Nothing matches right now.', btn: 'Reset search', act: () => root.reset() };
}

let sayT = 0;
function update(focusEl) {
  sizeAll();
  const q = read();
  const bad = isNaN(q.budget) || q.budget < 500 || q.budget > 9000;
  root.classList.toggle('is-invalid', bad);
  budgetIn.setAttribute('aria-invalid', String(bad));
  err.textContent = bad ? 'Enter a monthly budget between $500 and $9,000.' : '';
  go.classList.remove('is-done'); goLabel.textContent = 'Alert me';
  if (bad) { go.disabled = true; return; }
  const cands = L.filter(l => fits(l, q)), matches = cands.filter(l => l.rent <= q.budget), n = matches.length;
  setCount(n);
  noun.textContent = (n === 1 ? nounOf(q) : nounOf(q) + 's') + ' match';
  const rents = matches.map(l => l.rent).sort((p, r) => p - r);
  median.textContent = n ? (n === 1 ? usd(rents[0]) + ' a month' : 'median ' + usd(n % 2 ? rents[(n - 1) / 2] : (rents[n / 2 - 1] + rents[n / 2]) / 2) + ' · ' + cands.length + ' before budget') : cands.length + ' found above your budget';
  renderStrip(cands, q);
  root.classList.toggle('is-empty', !n);
  if (n) renderList(matches);
  else {
    const r = rescue(q, cands);
    empty.innerHTML = '<p>' + r.html + '</p><button type="button" data-rescue>' + esc(r.btn) + '</button>';
    empty.querySelector('[data-rescue]').onclick = () => {
      r.act(); update();
      root.querySelectorAll('select, input').forEach(el => { el.classList.remove('is-pulse'); });
      const f = root.querySelector('.mfm-sentence-go'); if (f && !f.disabled) f.focus({ preventScroll: true });
    };
  }
  go.disabled = !n;
  clearTimeout(sayT);
  sayT = setTimeout(() => { if (root.isConnected) live.textContent = n + ' ' + noun.textContent; }, 400);
}

root.addEventListener('change', e => {
  if (!e.target.matches('select')) return;
  e.target.classList.remove('is-pulse'); void e.target.offsetWidth; e.target.classList.add('is-pulse');
  update();
});
budgetIn.addEventListener('input', () => {
  const caretFromEnd = budgetIn.value.length - budgetIn.selectionEnd, n = parseBudget(budgetIn.value);
  if (!isNaN(n)) { budgetIn.value = n.toLocaleString('en-US'); const p = Math.max(0, budgetIn.value.length - caretFromEnd); budgetIn.setSelectionRange(p, p); }
  update();
});
budgetIn.addEventListener('keydown', e => {
  if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
  e.preventDefault();
  const n = parseBudget(budgetIn.value) || 0, step = e.shiftKey ? 250 : 50;
  budgetIn.value = Math.max(500, Math.min(9000, n + (e.key === 'ArrowUp' ? step : -step))).toLocaleString('en-US');
  update();
});
root.addEventListener('reset', () => setTimeout(() => { if (root.isConnected) update(); }, 0));
root.addEventListener('submit', e => {
  e.preventDefault();
  if (go.disabled || go.getAttribute('aria-busy') === 'true') return;
  const n = odo.getAttribute('aria-label');
  go.setAttribute('aria-busy', 'true'); goLabel.textContent = 'Saving';
  setTimeout(() => {
    if (!root.isConnected) return;
    go.removeAttribute('aria-busy'); go.classList.add('is-done');
    goLabel.textContent = 'Alert on · ' + n + ' today';
    live.textContent = 'Alert saved. We will email new matches.';
  }, 700);
});

let roFrame = 0, lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(roFrame);
  roFrame = requestAnimationFrame(() => {
    if (!root.isConnected) return;
    if (strip.clientWidth !== lastW) { lastW = strip.clientWidth; update(); }
  });
});
ro.observe(strip);
update();

