.mfm-webhook {
  /* re-theme with these four */
  --mfm-webhook-bg: oklch(0.185 0.015 242);
  --mfm-webhook-ink: oklch(0.94 0.01 230);
  --mfm-webhook-accent: oklch(0.84 0.12 190);
  --mfm-webhook-bad: oklch(0.71 0.17 25);

  --mfm-webhook-mute: color-mix(in oklch, var(--mfm-webhook-ink) 56%, var(--mfm-webhook-bg));
  --mfm-webhook-line: color-mix(in oklch, var(--mfm-webhook-ink) 12%, transparent);
  --mfm-webhook-well: color-mix(in oklch, var(--mfm-webhook-bg), black 28%);
  --mfm-webhook-raise: color-mix(in oklch, var(--mfm-webhook-ink) 5%, var(--mfm-webhook-bg));
  --mfm-webhook-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-webhook-out: cubic-bezier(.16, 1, .3, 1);
  --mfm-webhook-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px; max-height: 520px; margin: 0;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; border: 1px solid var(--mfm-webhook-line); overflow: hidden;
  background: var(--mfm-webhook-bg); color: var(--mfm-webhook-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--mfm-webhook-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-webhook-accent); outline-offset: 2px; }
  & code { font-family: var(--mfm-webhook-mono); font-size: .9em; }

  & .mfm-webhook-head {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: center;
    padding: 14px 16px; border-bottom: 1px solid var(--mfm-webhook-line);
    background: linear-gradient(180deg, color-mix(in oklch, var(--mfm-webhook-accent) 6%, transparent), transparent);
    & h3 { margin: 0; font-size: 14.5px; font-weight: 650; letter-spacing: -0.01em; }
    & p { margin: 1px 0 0; font-size: 12px; color: var(--mfm-webhook-mute); text-wrap: pretty; }
    & p code { color: var(--mfm-webhook-ink); }
  }
  & .mfm-webhook-logo {
    width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px;
    background: color-mix(in oklch, var(--mfm-webhook-accent) 14%, transparent); color: var(--mfm-webhook-accent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-webhook-accent) 28%, transparent);
    & svg { width: 18px; height: 18px; stroke-width: 1.8; }
  }
  & .mfm-webhook-mode {
    padding: 3px 7px; border-radius: 6px; font: 650 10px/1.2 var(--mfm-webhook-mono); letter-spacing: .04em; text-transform: uppercase;
    color: oklch(0.85 0.13 80); background: color-mix(in oklch, oklch(0.85 0.13 80) 13%, transparent);
  }

  & .mfm-webhook-body {
    min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 14px 16px 6px; display: grid; gap: 14px; align-content: start;
    scrollbar-width: thin; scrollbar-color: var(--mfm-webhook-line) transparent;
    mask-image: linear-gradient(#000 calc(100% - var(--mfm-webhook-fade)), transparent);
  }

  /* ── error summary: collapses on a 0fr → 1fr grid track ── */
  & .mfm-webhook-sum {
    display: grid; grid-template-rows: 0fr; margin-bottom: -14px; outline: none; visibility: hidden;
    transition: grid-template-rows .45s var(--mfm-webhook-out), margin .45s var(--mfm-webhook-out), visibility 0s linear .45s;
    &.is-on { grid-template-rows: 1fr; margin-bottom: 0; visibility: visible; transition-delay: 0s; }
    &:focus-visible .mfm-webhook-sumbox { outline: 2px solid var(--mfm-webhook-bad); outline-offset: 2px; }
    &.is-clear .mfm-webhook-sumbox { border-color: color-mix(in oklch, var(--mfm-webhook-accent) 45%, transparent); background: color-mix(in oklch, var(--mfm-webhook-accent) 8%, transparent); }
    &.is-clear .mfm-webhook-sumhead { color: var(--mfm-webhook-accent); }
  }
  & .mfm-webhook-sumin { min-height: 0; overflow: hidden; padding: 2px; margin: -2px; }
  & .mfm-webhook-sumbox {
    border-radius: 11px;
    border: 1px solid color-mix(in oklch, var(--mfm-webhook-bad) 45%, transparent);
    background: color-mix(in oklch, var(--mfm-webhook-bad) 9%, transparent);
    transition: background-color .3s, border-color .3s;
    & ul { list-style: none; margin: 0; padding: 0 12px 9px 34px; display: grid; }
  }
  & .mfm-webhook-sumhead {
    display: flex; align-items: center; gap: 8px; margin: 0; padding: 10px 12px 6px; font-size: 13px; font-weight: 640; color: var(--mfm-webhook-bad);
