}

@supports (animation-timeline: scroll()) {
  .mfm-webhook .mfm-webhook-body { animation: mfm-webhook-edge linear both; animation-timeline: scroll(self); }
}
@property --mfm-webhook-fade { syntax: '<length>'; inherits: false; initial-value: 0px; }
@keyframes mfm-webhook-edge { 0%, 90% { --mfm-webhook-fade: 28px; } 100% { --mfm-webhook-fade: 0px; } }
@keyframes mfm-webhook-line { from { opacity: 0; translate: 0 4px; } }
@keyframes mfm-webhook-caret { 50% { opacity: 0; } }
@keyframes mfm-webhook-draw { to { stroke-dashoffset: 0; } }
