@media (prefers-reduced-motion: reduce) {
  .mfm-webhook {
    & .mfm-webhook-sum, & .mfm-webhook-sumitem { transition: none; }
    & .mfm-webhook-log div, & .mfm-webhook-facts div { animation: none; }
    & .mfm-webhook-log .is-wait::after { animation: none; }
    & .mfm-webhook-okhead svg circle, & .mfm-webhook-okhead svg path { animation: none; stroke-dashoffset: 0; }
    & .mfm-webhook-lock, & .mfm-webhook-lock path { transition: color .2s; }
  }
