const $ = s => root.querySelector(s);
const inp = k => root.querySelector('[data-in="' + k + '"]');
const url = inp('url'), timeout = inp('timeout'), desc = inp('desc');
const evs = [...root.querySelectorAll('[data-ev]')], all = $('[data-all]'), evCount = $('[data-evcount]');
const sum = $('[data-sum]'), sumHead = $('[data-sumhead]'), sumList = $('[data-sumlist]');
const lock = $('[data-lock]'), log = $('[data-log]'), done = $('[data-done]'), note = $('[data-note]');
const go = $('[data-go]'), goLabel = $('[data-golabel]'), descCount = $('[data-desccount]');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const uid = 'mfm-webhook-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const ALERT = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="M8 4.8v3.6M8 11.1v.1"/></svg>';
const LABEL = { url: 'Endpoint URL', events: 'Events', timeout: 'Timeout', desc: 'Description' };
const FIELDS = ['url', 'events', 'timeout', 'desc'];
const box = k => root.querySelector('[data-f="' + k + '"]');
const msgEl = k => root.querySelector('[data-msg="' + k + '"]');

let touched = {}, submitted = false, busy = false, serverErr = null, created = null, shown = [];

/* ids and descriptions */
FIELDS.forEach(k => {
  const m = msgEl(k); m.id = uid + '-m-' + k; m.textContent = m.dataset.help;
  const i = k === 'events' ? evs[0] : inp(k);
  i.setAttribute('aria-describedby', m.id);
  if (k !== 'events') { i.id = uid + '-' + k; root.querySelector('[data-for="' + k + '"]').htmlFor = i.id; }
});

/* validity — the constraint API does the work; these only translate it into human copy */
function checkURL() {
  url.setCustomValidity('');
  const v = url.value.trim();
  if (serverErr && v === serverErr.url) url.setCustomValidity(serverErr.msg);
  else if (v && url.validity.valid && !/^https:\/\//i.test(v)) url.setCustomValidity('Use https:// — events carry billing data.');
  lock.classList.toggle('is-secure', /^https:\/\/[^/\s]+\.[^/\s]+/i.test(v) && url.validity.valid);
  lock.classList.toggle('is-open', /^http:\/\//i.test(v));
}
function checkEvents() {
  const n = evs.filter(e => e.checked).length;
  evs[0].setCustomValidity(n ? '' : 'Pick at least one event.');
  all.checked = n === evs.length; all.indeterminate = n > 0 && n < evs.length;
  evCount.textContent = n + ' / ' + evs.length;
}
function message(k) {
  if (k === 'url') {
    const v = url.validity;
    if (v.valueMissing) return 'Add the URL we should POST events to.';
    if (v.typeMismatch) return 'That isn’t a full URL — start with https://';
    if (v.customError) return url.validationMessage;
  }
  if (k === 'events') return evs[0].validity.customError ? 'Pick at least one event.' : '';
  if (k === 'timeout') {
    const v = timeout.validity;
    if (v.valueMissing || v.badInput) return 'Enter a number of seconds.';
    if (v.rangeUnderflow) return 'At least 1 second.';
    if (v.rangeOverflow) return 'Keep it to 30 seconds — slower endpoints get retried.';
    if (v.stepMismatch) return 'Whole seconds only.';
  }
  return '';
}
const invalid = k => !!message(k);

function paint(k) {
  const m = message(k), show = !!m && (touched[k] || submitted), b = box(k), el = msgEl(k);
  b.classList.toggle('is-err', show);
  b.classList.toggle('is-ok', !m && !!touched[k]);
  el.innerHTML = show ? ALERT + '<span>' + esc(m) + '</span>' : esc(el.dataset.help);
  (k === 'events' ? evs[0] : inp(k)).setAttribute('aria-invalid', String(show));
}
function paintAll() { checkURL(); checkEvents(); FIELDS.forEach(paint); paintSummary(); }

/* the summary lists what was wrong at the last submit, and strikes items off as they are fixed */
function paintSummary() {
  if (!shown.length) return;
  const left = shown.filter(invalid);
  sumList.querySelectorAll('[data-k]').forEach(li => li.classList.toggle('is-fixed', !invalid(li.dataset.k)));
  if (!left.length) {
    sum.classList.add('is-clear');
    sumHead.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="m5.4 8.2 1.8 1.8 3.5-3.8"/></svg>All fixed — ready to create.';
    clearTimeout(paintSummary.t);
    paintSummary.t = setTimeout(() => { if (root.isConnected && !shown.filter(invalid).length) { sum.classList.remove('is-on'); shown = []; } }, 1400);
  } else {
    sum.classList.remove('is-clear');
    sumHead.innerHTML = ALERT + left.length + (left.length === 1 ? ' field needs' : ' fields need') + ' attention';
  }
}
function openSummary(keys) {
  shown = keys;
  sumList.innerHTML = keys.map(k => '<li class="mfm-webhook-sumitem" data-k="' + k + '"><div><button type="button" data-goto="' + k + '"><b>' + LABEL[k] +
    '</b><span>— ' + esc(message(k)) + '</span></button></div></li>').join('');
  sum.classList.add('is-on'); sum.classList.remove('is-clear');
  paintSummary();
  sum.focus({ preventScroll: true });
  $('[data-body]').scrollTop = 0;
}

function hash(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function line(cls, html, wait) {
  const d = document.createElement('div'); d.className = cls + (wait ? ' is-wait' : ''); d.innerHTML = html; log.append(d); return d;
}

function submit() {
  if (busy) return;
  submitted = true; serverErr = null;
  paintAll();
  const bad = FIELDS.filter(invalid);
  if (bad.length) { openSummary(bad); return; }
  sum.classList.remove('is-on'); shown = [];
  busy = true; go.setAttribute('aria-busy', 'true'); goLabel.textContent = 'Sending test event';
  const u = url.value.trim(), host = (u.match(/^https:\/\/([^/:?#]+)/i) || [])[1] || '';
  const path = u.replace(/^https:\/\/[^/]+/i, '') || '/';
  const ev = evs.find(e => e.checked).value;
  log.innerHTML = '';
  line('is-out', '→ POST ' + esc(path.length > 26 ? path.slice(0, 25) + '…' : path) + ' · ' + esc(ev));
  const wait = line('is-out', '  waiting', true);
  const privateHost = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)|\.(local|internal|test)$/i.test(host);
  const ms = 120 + hash(u) % 170;
  setTimeout(() => {
    if (!root.isConnected) return;
    busy = false; go.removeAttribute('aria-busy'); goLabel.textContent = 'Create endpoint';
    wait.remove();
    if (privateHost) {
      line('is-bad', '← connection refused · ' + esc(host) + ' is not public');
      serverErr = { url: u, msg: 'We couldn’t reach ' + host + ' — localhost and private networks are blocked. Use a public URL or a tunnel.' };
      touched.url = true; paintAll(); openSummary(['url']);
      url.focus({ preventScroll: true });
      return;
    }
    line('is-ok', '← 200 OK · ' + ms + ' ms');
    created = { u, ms, n: evs.filter(e => e.checked).length, t: +timeout.value, secret: 'whsec_demo_' + hash(u + 'k').toString(36) + hash(u + 's').toString(36) };
    setTimeout(() => { if (root.isConnected) showDone(); }, RM.matches ? 0 : 650);
  }, RM.matches ? 300 : 1100);
}

function showDone() {
  const c = created, tail = c.secret.slice(-4);
  done.innerHTML = '<div class="mfm-webhook-okhead"><svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="13.5" pathLength="1"/><path d="m10.5 16.5 3.7 3.7 7.4-8" pathLength="1"/></svg>' +
    '<div><h4>Endpoint live</h4><p>' + (desc.value.trim() ? esc(desc.value.trim()) : 'Test events will appear in the delivery log') + '</p></div></div>' +
    '<code class="mfm-webhook-url">' + esc(c.u) + '</code>' +
    '<dl class="mfm-webhook-facts"><div style="--i:0"><dt>Events</dt><dd>' + c.n + '</dd></div><div style="--i:1"><dt>Timeout</dt><dd>' + c.t + ' s</dd></div>' +
    '<div style="--i:2"><dt>Last test</dt><dd>' + c.ms + ' ms</dd></div></dl>' +
    '<div class="mfm-webhook-secret"><span>Signing secret · verify the <code>Tillwright-Signature</code> header</span><code data-secret>whsec_' + '•'.repeat(14) + tail + '</code>' +
    '<button type="button" data-reveal aria-pressed="false">Reveal</button><button type="button" data-copy>Copy</button></div>';
  root.classList.add('is-done');
  note.textContent = 'Created just now · 200 OK';
  goLabel.textContent = 'Add another';
  done.focus({ preventScroll: true });
}

function reset() {
  created = null; submitted = false; touched = {}; serverErr = null; shown = [];
  root.classList.remove('is-done'); done.innerHTML = ''; log.innerHTML = ''; sum.classList.remove('is-on');
  url.value = ''; desc.value = ''; timeout.value = '10';
  evs.forEach((e, i) => { e.checked = i < 2; });
  descCount.textContent = '0/40'; note.textContent = 'Retries for 3 days with backoff';
  goLabel.textContent = 'Create endpoint';
  paintAll(); url.focus({ preventScroll: true });
}

/* events */
root.addEventListener('submit', e => { e.preventDefault(); if (created) reset(); else submit(); });
root.addEventListener('input', e => {
  const k = e.target.dataset.in;
  if (k === 'desc') descCount.textContent = desc.value.length + '/40';
  if (k === 'url' && serverErr && url.value.trim() !== serverErr.url) serverErr = null;
  checkURL(); checkEvents();
  if (k) paint(k);
  paintSummary();
});
root.addEventListener('focusout', e => {
  const k = e.target.dataset && e.target.dataset.in;
  if (k && e.target.value !== '') { touched[k] = true; paint(k); paintSummary(); }
});
root.addEventListener('change', e => {
  if (e.target === all) evs.forEach(x => { x.checked = all.checked; });
  if (e.target === all || e.target.hasAttribute('data-ev')) { touched.events = true; checkEvents(); paint('events'); paintSummary(); }
  if (e.target.dataset.in) { touched[e.target.dataset.in] = true; paint(e.target.dataset.in); paintSummary(); }
});
root.addEventListener('click', e => {
  const g = e.target.closest('[data-goto]');
  if (g) { const k = g.dataset.goto; (k === 'events' ? evs[0] : inp(k)).focus(); return; }
  const r = e.target.closest('[data-reveal]');
  if (r) {
    const on = r.getAttribute('aria-pressed') !== 'true', s = root.querySelector('[data-secret]');
    r.setAttribute('aria-pressed', String(on)); r.textContent = on ? 'Hide' : 'Reveal';
    s.textContent = on ? created.secret : 'whsec_' + '•'.repeat(14) + created.secret.slice(-4);
    return;
  }
  const c = e.target.closest('[data-copy]');
  if (c) {
    const ok = () => { c.textContent = 'Copied'; setTimeout(() => { if (root.isConnected) c.textContent = 'Copy'; }, 1500); };
    try { navigator.clipboard.writeText(created.secret).then(ok, () => { c.textContent = 'Press ⌘C'; }); } catch (err) { c.textContent = 'Press ⌘C'; }
  }
});

note.textContent = 'Retries for 3 days with backoff';
paintAll();

css:
.mfm-sign {
  /* re-theme with these five */
  --mfm-sign-bg: oklch(0.983 0.009 88);
  --mfm-sign-ink: oklch(0.25 0.02 265);
  --mfm-sign-pen: oklch(0.32 0.09 266);
  --mfm-sign-accent: oklch(0.49 0.16 22);
  --mfm-sign-ok: oklch(0.52 0.11 155);

  --mfm-sign-mute: color-mix(in oklch, var(--mfm-sign-ink) 55%, var(--mfm-sign-bg));
  --mfm-sign-line: color-mix(in oklch, var(--mfm-sign-ink) 12%, transparent);
  --mfm-sign-soft: color-mix(in oklch, var(--mfm-sign-ink) 5%, var(--mfm-sign-bg));
  --mfm-sign-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mfm-sign-out: cubic-bezier(.16, 1, .3, 1);
  --mfm-sign-script: "Snell Roundhand", "Segoe Script", "Bradley Hand", "Brush Script MT", cursive;

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box;
  width: 100%; max-width: 420px;
  display: grid; gap: 13px; padding: 16px 16px 14px;
  border-radius: 16px; background: var(--mfm-sign-bg); color: var(--mfm-sign-ink);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-sign-ink) 9%, transparent), 0 24px 48px -26px oklch(0 0 0 / .55);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--mfm-sign-pen);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mfm-sign-pen); outline-offset: 2px; }

  & .mfm-sign-head {
    & h3 { margin: 2px 0 10px; font: 600 clamp(1.05rem, .8rem + 2.4cqi, 1.24rem)/1.2 ui-serif, Georgia, serif; letter-spacing: -0.01em; text-wrap: balance; }
  }
  & .mfm-sign-eyebrow { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--mfm-sign-mute); }
  & .mfm-sign-terms {
    display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); margin: 0; border-block: 1px solid var(--mfm-sign-line);
    & div { padding: 7px 0 7px 10px; & + div { border-left: 1px solid var(--mfm-sign-line); } &:first-child { padding-left: 0; } }
    & dt { font-size: 11px; color: var(--mfm-sign-mute); }
    & dd { margin: 0; font-size: 13.5px; font-weight: 640; font-variant-numeric: tabular-nums; white-space: nowrap; }
    & small { font-size: 11px; font-weight: 450; color: var(--mfm-sign-mute); margin-left: 3px; }
  }

  & .mfm-sign-bar { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
  & .mfm-sign-tabs {
    position: relative; display: inline-grid; grid-auto-flow: column; grid-auto-columns: 1fr; padding: 3px; border-radius: 10px;
    background: var(--mfm-sign-soft); box-shadow: inset 0 0 0 1px var(--mfm-sign-line);
    & button {
      position: relative; z-index: 1; height: 28px; padding: 0 14px; border: 0; border-radius: 7px; background: none;
      font-size: 12.5px; font-weight: 600; color: var(--mfm-sign-mute); transition: color .2s;
      &[aria-selected="true"] { color: var(--mfm-sign-ink); }
    }
  }
  & .mfm-sign-ind {
    position: absolute; top: 3px; bottom: 3px; left: 3px; width: calc(50% - 3px); border-radius: 7px; background: white;
    box-shadow: 0 1px 2px oklch(0 0 0 / .1), 0 0 0 1px var(--mfm-sign-line);
    transition: translate .45s var(--mfm-sign-spring);
  }
  &[data-mode="type"] .mfm-sign-ind { translate: 100% 0; }
  & .mfm-sign-tools {
    display: flex; gap: 4px;
    & button {
      height: 30px; min-width: 30px; padding: 0 9px; display: inline-grid; place-items: center; border: 0; border-radius: 8px; background: transparent;
      font-size: 12.5px; font-weight: 600; color: var(--mfm-sign-mute); transition: background-color .15s, color .15s;
      & svg { width: 15px; height: 15px; }
      &:hover:not(:disabled) { background: var(--mfm-sign-soft); color: var(--mfm-sign-ink); }
      &:disabled { opacity: .35; cursor: default; }
    }
  }

  & .mfm-sign-pad {
    position: relative; height: 150px; border-radius: 12px; overflow: hidden;
    background:
      linear-gradient(transparent calc(100% - 37px), var(--mfm-sign-line) calc(100% - 37px), var(--mfm-sign-line) calc(100% - 36px), transparent calc(100% - 36px)),
      white;
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mfm-sign-ink) 14%, transparent), inset 0 2px 8px -4px oklch(0 0 0 / .08);
    transition: box-shadow .2s;
    &:has(canvas:focus-visible) { box-shadow: inset 0 0 0 2px var(--mfm-sign-pen); }
    & canvas { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; outline: none; }
  }
  & .mfm-sign-ph {
    position: absolute; left: 0; right: 0; bottom: 44px; text-align: center; pointer-events: none;
    font: italic 400 clamp(1.3rem, 1rem + 3cqi, 1.6rem)/1 ui-serif, Georgia, serif; color: color-mix(in oklch, var(--mfm-sign-ink) 22%, transparent);
    transition: opacity .3s, translate .4s var(--mfm-sign-out), filter .3s;
  }
  &.has-ink .mfm-sign-ph { opacity: 0; translate: 0 -6px; filter: blur(3px); }
  & .mfm-sign-line {
    position: absolute; left: 14px; bottom: 39px; width: 12px; height: 12px; color: color-mix(in oklch, var(--mfm-sign-ink) 45%, transparent); pointer-events: none;
    & svg { width: 12px; height: 12px; stroke-width: 1.8; }
  }
  & .mfm-sign-pad.is-typed {
    display: grid; align-items: end;
    & input {
      position: absolute; left: 12px; right: 12px; top: 12px; height: 34px; padding: 0 10px; border-radius: 8px; background: var(--mfm-sign-soft);
      border: 1px solid var(--mfm-sign-line); font: 500 13.5px/1 system-ui, -apple-system, sans-serif; color: var(--mfm-sign-ink);
      &:focus { outline: none; border-color: var(--mfm-sign-pen); box-shadow: 0 0 0 3px color-mix(in oklch, var(--mfm-sign-pen) 16%, transparent); }
      &[aria-invalid="true"] { border-color: var(--mfm-sign-accent); }
    }
  }
  & .mfm-sign-script {
    position: absolute; left: 34px; right: 14px; bottom: 30px; font: 400 clamp(1.7rem, 1.2rem + 4cqi, 2.3rem)/1.1 var(--mfm-sign-script);
    color: var(--mfm-sign-pen); white-space: nowrap; overflow: hidden; text-overflow: clip; pointer-events: none;
    & span { display: inline-block; animation: mfm-sign-ink .35s var(--mfm-sign-out) both; }
  }

  & .mfm-sign-seal {
    position: absolute; right: 12px; top: 10px; width: 84px; height: 84px; pointer-events: none; opacity: 0;
    color: var(--mfm-sign-accent); rotate: -14deg;
    & svg { width: 100%; height: 100%; }
    & text { fill: currentColor; stroke: none; font: 700 7.2px/1 system-ui, -apple-system, sans-serif; letter-spacing: .16em; }
    & .mfm-sign-sealdate { font: 800 9px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; text-anchor: middle; }
  }
  &.is-sealed {
    & .mfm-sign-seal { opacity: .88; animation: mfm-sign-stamp .55s cubic-bezier(.2, 1.4, .4, 1) both; mix-blend-mode: multiply; }
    & .mfm-sign-pad canvas { cursor: default; }
    & .mfm-sign-tabs { opacity: .5; pointer-events: none; }
  }

  & .mfm-sign-consent {
    display: grid; grid-template-columns: auto 1fr; gap: 9px; align-items: start; font-size: 12.5px; line-height: 1.4; color: color-mix(in oklch, var(--mfm-sign-ink) 82%, transparent); cursor: pointer;
    & input { width: 16px; height: 16px; margin: 1px 0 0; }
    & span { text-wrap: pretty; }
  }
  &.is-sealed .mfm-sign-consent { opacity: .55; pointer-events: none; }

  & .mfm-sign-foot { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px; padding-top: 12px; border-top: 1px solid var(--mfm-sign-line); }
  & .mfm-sign-status {
    margin: 0; font-size: 12px; line-height: 1.35; color: var(--mfm-sign-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
    & b { color: var(--mfm-sign-ink); font-weight: 620; }
    & code { font: 500 11px/1 ui-monospace, Menlo, monospace; }
    &.is-err { color: var(--mfm-sign-accent); font-weight: 500; }
    &.is-ok { color: color-mix(in oklch, var(--mfm-sign-ok), black 12%); }
  }
  & .mfm-sign-go {
    display: inline-flex; align-items: center; gap: 7px; height: 38px; padding: 0 18px; border: 0; border-radius: 11px;
    background: var(--mfm-sign-pen); color: white; font-weight: 640; font-size: 13.5px; white-space: nowrap;
    box-shadow: 0 8px 20px -10px var(--mfm-sign-pen);
    transition: background-color .2s, color .2s, box-shadow .2s, transform .35s var(--mfm-sign-spring);
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mfm-sign-pen), black 15%); }
    &:active:not(:disabled) { transform: scale(.95); }
    &:disabled { background: var(--mfm-sign-soft); color: color-mix(in oklch, var(--mfm-sign-ink) 35%, transparent); box-shadow: inset 0 0 0 1px var(--mfm-sign-line); cursor: not-allowed; }
    &[aria-busy="true"] { pointer-events: none; & .mfm-sign-spin { display: block; } }
  }
  & .mfm-sign-spin {
    display: none; width: 13px; height: 13px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, white 35%, transparent); border-top-color: white; animation: mfm-sign-spin .7s linear infinite;
  }

  @container (max-width: 290px) {
    & { padding: 14px 13px 13px; }
    & .mfm-sign-terms { grid-template-columns: repeat(3, auto); justify-content: space-between; & dd { font-size: 12.5px; } & div + div { padding-left: 9px; } }
    & .mfm-sign-terms small { display: none; }
    & .mfm-sign-pad { height: 136px; }
    & .mfm-sign-seal { width: 68px; height: 68px; }
    & .mfm-sign-foot { grid-template-columns: 1fr; }
    & .mfm-sign-go { justify-content: center; }
  }
}

@keyframes mfm-sign-stamp { 0% { opacity: 0; scale: 1.9; rotate: -4deg; filter: blur(2px); } 60% { opacity: .95; scale: .94; filter: blur(0); } 100% { opacity: .88; scale: 1; rotate: -14deg; } }
@keyframes mfm-sign-ink { from { opacity: 0; filter: blur(2px); translate: -3px 0; } }
@keyframes mfm-sign-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mfm-sign {
    & .mfm-sign-ind { transition: none; }
    & .mfm-sign-ph { transition: opacity .2s; translate: none; filter: none; }
    &.is-sealed .mfm-sign-seal { animation: none; }
    & .mfm-sign-script span { animation: none; }
  }
}

