const $ = s => root.querySelector(s);
const cv = $('[data-canvas]'), ctx = cv.getContext('2d'), seal = $('[data-seal]'), tools = $('[data-tools]');
const typed = $('[data-typed]'), script = $('[data-script]'), consent = $('[data-consent]');
const status = $('[data-status]'), go = $('[data-go]'), goLabel = $('[data-golabel]');
const tabs = [...root.querySelectorAll('[role="tab"]')], panels = [...root.querySelectorAll('[role="tabpanel"]')];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const uid = 'mfm-sign-' + Math.random().toString(36).slice(2, 8);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const SIGNER = 'Dana Whitfield', REF = 320;
const TOOLS = tools.innerHTML;

/* strokes live in reference units (320 = pad width) so a resize simply rescales them */
let W = 0, H = 0, dpr = 1, strokes = [], cur = null, box = null, sealed = false, mode = 'draw', raf = 0, ink = '#2b3166';
const k = () => W / REF;

function resolveInk() {
  const raw = getComputedStyle(root).getPropertyValue('--mfm-sign-pen').trim();
  ctx.strokeStyle = '#2b3166';
  if (raw) ctx.strokeStyle = raw;
  ink = ctx.strokeStyle;
}
function resize() {
  const r = cv.getBoundingClientRect();
  if (!r.width) return;
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  redraw();
}
function prep() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.strokeStyle = ink; ctx.fillStyle = ink;
}
/* one point's worth of ink: a dot to start, then quadratic curves between midpoints */
function piece(st, i, s) {
  const p = st.pts, b = p[i];
  ctx.beginPath();
  if (i === 0) { ctx.arc(b.x * s, b.y * s, b.w * s / 2, 0, Math.PI * 2); ctx.fill(); return; }
  const a = p[i - 1];
  if (i === 1) ctx.moveTo(a.x * s, a.y * s);
  else { const z = p[i - 2]; ctx.moveTo((z.x + a.x) / 2 * s, (z.y + a.y) / 2 * s); }
  ctx.quadraticCurveTo(a.x * s, a.y * s, (a.x + b.x) / 2 * s, (a.y + b.y) / 2 * s);
  ctx.lineWidth = Math.max(.6, (a.w + b.w) / 2 * s);
  ctx.stroke();
}
function tail(st, s) {
  const p = st.pts, n = p.length;
  if (n < 2) return;
  const a = p[n - 2], b = p[n - 1];
  ctx.beginPath(); ctx.moveTo((a.x + b.x) / 2 * s, (a.y + b.y) / 2 * s); ctx.lineTo(b.x * s, b.y * s);
  ctx.lineWidth = Math.max(.6, b.w * s); ctx.stroke();
}
function redraw() {
  prep(); ctx.clearRect(0, 0, W, H);
  const s = k();
  strokes.forEach(st => { st.pts.forEach((_, i) => piece(st, i, s)); tail(st, s); });
}

function addPt(e) {
  const s = k(), x = (e.clientX - box.left) / s, y = (e.clientY - box.top) / s, t = e.timeStamp - cur.t0;
  const p = cur.pts, last = p[p.length - 1];
  let w = 2.6;
  if (last) {
    const d = Math.hypot(x - last.x, y - last.y);
    if (d < .7) return;
    const v = d / Math.max(1, t - last.t);
    const target = e.pointerType === 'pen' && e.pressure > 0 ? .9 + e.pressure * 3 : Math.max(1.05, Math.min(3.4, 3.5 - v * 1.5));
    w = last.w * .62 + target * .38;
  }
  p.push({ x, y, t, w });
  piece(cur, p.length - 1, s);
}
cv.addEventListener('pointerdown', e => {
  if (sealed || mode !== 'draw' || (e.pointerType === 'mouse' && e.button !== 0)) return;
  e.preventDefault();
  cancelAnimationFrame(raf); raf = 0;
  try { cv.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointer */ }
  box = cv.getBoundingClientRect(); prep();
  cur = { t0: e.timeStamp, pts: [] }; strokes.push(cur);
  addPt(e);
  root.classList.add('has-ink');
});
cv.addEventListener('pointermove', e => {
  if (!cur) return;
  const list = e.getCoalescedEvents ? e.getCoalescedEvents() : [];
  (list.length ? list : [e]).forEach(addPt);
});
const end = () => { if (!cur) return; tail(cur, k()); cur = null; changed(); };
cv.addEventListener('pointerup', end); cv.addEventListener('pointercancel', end); cv.addEventListener('lostpointercapture', end);

/* replay: the signature redraws itself at the speed it was signed (gaps between strokes capped) */
function replay() {
  if (!strokes.length) return;
  cancelAnimationFrame(raf);
  if (RM.matches) { redraw(); return; }
  let at = 0, prevEnd = null;
  const plan = strokes.map(st => {
    const dur = st.pts[st.pts.length - 1].t;
    if (prevEnd != null) at += Math.max(90, Math.min(320, st.t0 - prevEnd));
    const p = { st, start: at, n: 0, done: false };
    at += dur; prevEnd = st.t0 + dur;
    return p;
  });
  prep(); ctx.clearRect(0, 0, W, H);
  const t0 = performance.now(), s = k();
  const frame = now => {
    if (!root.isConnected) return;
    const el = (now - t0) * 1.1;
    let more = false;
    plan.forEach(p => {
      const pts = p.st.pts;
      while (p.n < pts.length && p.start + pts[p.n].t <= el) { piece(p.st, p.n, s); p.n++; }
      if (p.n < pts.length) more = true; else if (!p.done) { tail(p.st, s); p.done = true; }
    });
    raf = more ? requestAnimationFrame(frame) : 0;
  };
  raf = requestAnimationFrame(frame);
}

/* state */
const hasSig = () => mode === 'draw' ? strokes.length > 0 : typed.value.trim().length >= 2;
function setStatus(html, kind) { status.className = 'mfm-sign-status' + (kind ? ' is-' + kind : ''); status.innerHTML = html; }
function changed() {
  if (sealed) return;
  const n = strokes.length;
  tools.querySelector('[data-undo]') && (tools.querySelector('[data-undo]').disabled = mode !== 'draw' || !n);
  tools.querySelector('[data-clear]') && (tools.querySelector('[data-clear]').disabled = mode === 'draw' ? !n : !typed.value);
  root.classList.toggle('has-ink', n > 0);
  cv.setAttribute('aria-label', n ? 'Signature pad, ' + n + (n === 1 ? ' stroke' : ' strokes') + ' drawn. Undo with Control or Command Z.' : 'Signature pad, empty. Use the Type tab to sign with the keyboard.');
  go.disabled = !(hasSig() && consent.checked);
  typed.removeAttribute('aria-invalid');
  setStatus(hasSig() && consent.checked ? 'Ready — signing as <b>' + SIGNER + '</b>, tenant.'
    : hasSig() ? 'Tick the consent box to continue.' : 'Signing as <b>' + SIGNER + '</b>. Draw or type your signature.');
}
function undo() { if (sealed || !strokes.length) return; strokes.pop(); redraw(); changed(); }
function clear() {
  if (sealed) return;
  if (mode === 'type') { typed.value = ''; renderScript(); changed(); typed.focus(); return; }
  const wipe = () => { strokes = []; redraw(); changed(); };
  if (RM.matches) { wipe(); return; }
  cv.animate([{ opacity: 1, filter: 'blur(0)' }, { opacity: 0, filter: 'blur(4px)' }], { duration: 180, easing: 'ease-in' }).finished.then(() => { if (root.isConnected) wipe(); });
}

let shown = '';
function renderScript() {
  const v = typed.value;
  if (v.startsWith(shown) && !RM.matches) script.insertAdjacentHTML('beforeend', Array.from(v.slice(shown.length), c => '<span>' + (c === ' ' ? '&nbsp;' : esc(c)) + '</span>').join(''));
  else script.innerHTML = Array.from(v, c => '<span style="animation:none">' + (c === ' ' ? '&nbsp;' : esc(c)) + '</span>').join('');
  shown = v;
}

function setMode(m, focusTab) {
  if (sealed || m === mode) return;
  mode = m; root.dataset.mode = m;
  tabs.forEach(t => { const on = t.dataset.tab === m; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; if (on && focusTab) t.focus(); });
  panels.forEach(p => { p.hidden = p.dataset.panel !== m; });
  if (m === 'draw') { resize(); }
  changed();
}

function hash() {
  let h1 = 2166136261, h2 = 5381;
  const src = mode === 'draw' ? strokes.flatMap(st => st.pts.map(p => (p.x * 10 | 0) + ',' + (p.y * 10 | 0))).join(';') : typed.value;
  for (let i = 0; i < src.length; i++) { const c = src.charCodeAt(i); h1 = Math.imul(h1 ^ c, 16777619); h2 = (Math.imul(h2, 33) ^ c) >>> 0; }
  const hex = (h1 >>> 0).toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
  return hex.match(/.{4}/g).join(' ');
}
function stamp(d) {
  const mon = d.toLocaleString('en-US', { month: 'short' }).toUpperCase(), dd = String(d.getDate()).padStart(2, '0');
  seal.innerHTML = '<svg viewBox="0 0 100 100"><defs><path id="' + uid + '-arc" d="M50 50m-37 0a37 37 0 1 1 74 0a37 37 0 1 1-74 0"/></defs>' +
    '<circle cx="50" cy="50" r="46" stroke-width="2.6"/><circle cx="50" cy="50" r="43" stroke-width=".8"/><circle cx="50" cy="50" r="29" stroke-width="1.2"/>' +
    '<text><textPath href="#' + uid + '-arc" textLength="226" lengthAdjust="spacing">ELECTRONICALLY SIGNED · MARLOWE COURT ·</textPath></text>' +
    '<text class="mfm-sign-sealdate" x="50" y="48">' + dd + ' ' + mon + '</text><text class="mfm-sign-sealdate" x="50" y="60">' + d.getFullYear() + '</text></svg>';
}

function sign() {
  if (go.disabled || sealed) return;
  if (mode === 'draw') {
    const xs = strokes.flatMap(st => st.pts.map(p => p.x)), n = xs.length;
    if (Math.max(...xs) - Math.min(...xs) < 46 || n < 12) {
      setStatus('That’s a little small — sign across the line with your full signature.', 'err');
      if (!RM.matches) $('[data-pad]').animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-6px)' }, { transform: 'translateX(5px)' }, { transform: 'translateX(0)' }], { duration: 320, easing: 'cubic-bezier(.36,.07,.19,.97)' });
      return;
    }
  } else if (typed.value.trim().replace(/\s+/g, ' ').toLowerCase() !== SIGNER.toLowerCase()) {
    typed.setAttribute('aria-invalid', 'true');
    setStatus('Type the name on the lease exactly: <b>' + SIGNER + '</b>.', 'err');
    typed.focus();
    return;
  }
  go.setAttribute('aria-busy', 'true'); goLabel.textContent = 'Sealing';
  setTimeout(() => {
    if (!root.isConnected) return;
    const d = new Date();
    sealed = true; go.removeAttribute('aria-busy'); go.disabled = true; goLabel.textContent = 'Signed';
    stamp(d);
    root.classList.add('is-sealed');
    tools.innerHTML = (mode === 'draw' ? '<button type="button" data-replay>Replay</button>' : '') + '<button type="button" data-restart>Start over</button>';
    const time = d.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
    setStatus('Signed ' + esc(time) + ' · hash <code>' + hash().slice(0, 14) + '…</code>', 'ok');
    if (mode === 'draw') setTimeout(() => { if (root.isConnected) replay(); }, 380);
  }, 900);
}
function restart() {
  cancelAnimationFrame(raf); raf = 0;
  sealed = false; root.classList.remove('is-sealed'); seal.innerHTML = '';
  strokes = []; typed.value = ''; shown = ''; script.innerHTML = ''; consent.checked = false;
  tools.innerHTML = TOOLS; goLabel.textContent = 'Sign';
  redraw(); changed();
  (mode === 'draw' ? cv : typed).focus({ preventScroll: true });
}

/* wiring */
root.addEventListener('click', e => {
  const t = e.target.closest('[role="tab"]'); if (t) { setMode(t.dataset.tab); return; }
  if (e.target.closest('[data-undo]')) undo();
  else if (e.target.closest('[data-clear]')) clear();
  else if (e.target.closest('[data-replay]')) replay();
  else if (e.target.closest('[data-restart]')) restart();
});
$('[data-tabs]').addEventListener('keydown', e => {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight' && e.key !== 'Home' && e.key !== 'End') return;
  e.preventDefault();
  setMode(e.key === 'ArrowLeft' || e.key === 'Home' ? 'draw' : 'type', true);
});
cv.addEventListener('keydown', e => {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); undo(); }
});
typed.addEventListener('input', () => { renderScript(); changed(); });
consent.addEventListener('change', changed);
go.addEventListener('click', sign);

let roFrame = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(roFrame);
  roFrame = requestAnimationFrame(() => {
    if (!root.isConnected) return;
    const r = cv.getBoundingClientRect();
    if (mode === 'draw' && !raf && (Math.round(r.width) !== Math.round(W) || Math.round(r.height) !== Math.round(H))) resize();
  });
});
ro.observe(cv);
resolveInk();
resize();
changed();
